"""Build the printable chapters of the AI Assistant teaching manual."""
from __future__ import annotations

from pathlib import Path
from xml.sax.saxutils import escape

from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER, TA_LEFT
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
from reportlab.lib.units import mm
from reportlab.platypus import (BaseDocTemplate, Frame, PageTemplate, Paragraph,
                                PageBreak, Spacer, Table, TableStyle, KeepTogether,
                                HRFlowable, ListFlowable, ListItem)

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "manuals"
NAVY = colors.HexColor("#16324F")
TEAL = colors.HexColor("#147D83")
PALE = colors.HexColor("#EAF3F5")
INK = colors.HexColor("#243447")
MUTED = colors.HexColor("#607080")
GOLD = colors.HexColor("#D9A441")
WHITE = colors.white

styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name="CoverTitle2", parent=styles["Title"], fontName="Helvetica-Bold", fontSize=30, leading=36, textColor=WHITE, alignment=TA_LEFT, spaceAfter=12))
styles.add(ParagraphStyle(name="CoverSub", parent=styles["Normal"], fontSize=13, leading=19, textColor=colors.HexColor("#DCEAF2")))
styles.add(ParagraphStyle(name="H1x", parent=styles["Heading1"], fontName="Helvetica-Bold", fontSize=19, leading=23, textColor=NAVY, spaceBefore=10, spaceAfter=9, keepWithNext=True))
styles.add(ParagraphStyle(name="H2x", parent=styles["Heading2"], fontName="Helvetica-Bold", fontSize=13, leading=17, textColor=TEAL, spaceBefore=10, spaceAfter=5, keepWithNext=True))
styles.add(ParagraphStyle(name="H3x", parent=styles["Heading3"], fontName="Helvetica-Bold", fontSize=10.3, leading=13.5, textColor=NAVY, spaceBefore=7, spaceAfter=3, keepWithNext=True))
styles.add(ParagraphStyle(name="Bodyx", parent=styles["BodyText"], fontName="Helvetica", fontSize=9.2, leading=13.2, textColor=INK, spaceAfter=6))
styles.add(ParagraphStyle(name="Smallx", parent=styles["BodyText"], fontName="Helvetica", fontSize=7.6, leading=10.2, textColor=MUTED, spaceAfter=4))
styles.add(ParagraphStyle(name="Bulletx", parent=styles["BodyText"], fontName="Helvetica", fontSize=9, leading=12.5, textColor=INK, leftIndent=13, firstLineIndent=-8, spaceAfter=3))
styles.add(ParagraphStyle(name="TableHeadx", parent=styles["BodyText"], fontName="Helvetica-Bold", fontSize=8, leading=10, textColor=WHITE))
styles.add(ParagraphStyle(name="TableCellx", parent=styles["BodyText"], fontName="Helvetica", fontSize=7.7, leading=10, textColor=INK))
styles.add(ParagraphStyle(name="Calloutx", parent=styles["BodyText"], fontName="Helvetica", fontSize=9, leading=13, textColor=NAVY, leftIndent=8, rightIndent=8, spaceAfter=3))
styles.add(ParagraphStyle(name="Contentsx", parent=styles["BodyText"], fontName="Helvetica", fontSize=9, leading=14, textColor=INK, leftIndent=8, spaceAfter=3))

def P(text: str, style="Bodyx"):
    return Paragraph(text, styles[style])

def bullets(items):
    return [P("&#8226; " + item, "Bulletx") for item in items]

def callout(title, body, color=PALE):
    tbl = Table([[P(f"<b>{title}</b><br/>{body}", "Calloutx")]], colWidths=[170*mm])
    tbl.setStyle(TableStyle([("BACKGROUND", (0,0),(-1,-1),color), ("BOX",(0,0),(-1,-1),0.7,TEAL), ("LEFTPADDING",(0,0),(-1,-1),9), ("RIGHTPADDING",(0,0),(-1,-1),9), ("TOPPADDING",(0,0),(-1,-1),7), ("BOTTOMPADDING",(0,0),(-1,-1),7)]))
    return tbl

def table(headers, rows, widths=None):
    data = [[P(str(x), "TableHeadx") for x in headers]]
    data += [[P(str(x), "TableCellx") for x in row] for row in rows]
    t = Table(data, colWidths=widths, repeatRows=1, hAlign="LEFT")
    t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),NAVY), ("ROWBACKGROUNDS",(0,1),(-1,-1),[WHITE,colors.HexColor("#F4F7F9")]), ("GRID",(0,0),(-1,-1),0.35,colors.HexColor("#C8D3DC")), ("VALIGN",(0,0),(-1,-1),"TOP"), ("LEFTPADDING",(0,0),(-1,-1),5), ("RIGHTPADDING",(0,0),(-1,-1),5), ("TOPPADDING",(0,0),(-1,-1),5), ("BOTTOMPADDING",(0,0),(-1,-1),5)]))
    return [t]

def title(text, level=1):
    return P(text, {1:"H1x",2:"H2x",3:"H3x"}[level])

def section(num, name, paras=(), subs=()):
    out = [title(f"{num}. {name}")]
    for p in paras: out.append(P(p))
    for sub in subs:
        out.append(title(sub[0], 2))
        for p in sub[1]: out.append(P(p))
        if len(sub)>2 and sub[2]: out.extend(bullets(sub[2]))
    return out

def on_page(canvas, doc):
    canvas.saveState()
    w,h=A4
    if doc.page > 1:
        canvas.setStrokeColor(colors.HexColor("#D5DEE5")); canvas.setLineWidth(.5)
        canvas.line(20*mm,h-15*mm,w-20*mm,h-15*mm)
        canvas.setFont("Helvetica-Bold",7.5); canvas.setFillColor(NAVY)
        canvas.drawString(20*mm,h-11.5*mm,"INDIAN PEDIATRICS | AI ASSISTANT | IMPLEMENTATION MANUAL V1.0")
        canvas.setStrokeColor(colors.HexColor("#D5DEE5")); canvas.line(20*mm,14*mm,w-20*mm,14*mm)
        canvas.setFont("Helvetica",7.5); canvas.setFillColor(MUTED)
        canvas.drawString(20*mm,9.5*mm,doc.chapter_label)
        canvas.drawRightString(w-20*mm,9.5*mm,f"Page {doc.page}")
    canvas.restoreState()

def cover(story, chapter, subtitle, summary, version="Teaching manual installment 1.0 | October 2026"):
    story.append(Spacer(1,14*mm))
    panel=Table([[P("INDIAN PEDIATRICS<br/>AI ASSISTANT", "CoverSub")],[P(chapter,"CoverTitle2")],[P(subtitle,"CoverSub")],[Spacer(1,14*mm)],[P(summary,"CoverSub")],[Spacer(1,13*mm)],[P(version,"CoverSub")]], colWidths=[170*mm])
    panel.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,-1),NAVY),("LEFTPADDING",(0,0),(-1,-1),17),("RIGHTPADDING",(0,0),(-1,-1),17),("TOPPADDING",(0,0),(-1,-1),11),("BOTTOMPADDING",(0,0),(-1,-1),11),("LINEBEFORE",(0,0),(0,-1),5,GOLD)]))
    story.append(panel)
    story.append(Spacer(1,12*mm))
    story.append(P("Project: Reusable medical-journal literature assistant<br/>POC corpus: Indian Pediatrics, January 2025, Volume 62, Issue 1<br/>Audience: AI students and developers learning to plan and build a grounded literature assistant", "Bodyx"))
    story.append(callout("How to use this installment", "These are the first chapters of a cumulative teaching manual. They explain decisions made so far and provide a reproducible way to understand them. The full 300+ page reference is intended to grow as later roadmap phases are completed."))
    story.append(PageBreak())

def make_pdf(filename, chapter_label, story):
    OUT.mkdir(parents=True, exist_ok=True)
    doc=BaseDocTemplate(str(OUT/filename), pagesize=A4, leftMargin=20*mm, rightMargin=20*mm, topMargin=21*mm, bottomMargin=20*mm, title=chapter_label, author="Indian Pediatrics AI Assistant Project")
    frame=Frame(doc.leftMargin,doc.bottomMargin,doc.width,doc.height,id="normal",leftPadding=0,rightPadding=0,topPadding=0,bottomPadding=0)
    doc.addPageTemplates([PageTemplate(id="main",frames=[frame],onPage=on_page)])
    doc.chapter_label=chapter_label
    doc.build(story)

def add_glossary(story, rows):
    story.append(title("Glossary",1)); story.extend(table(["Term","Plain-language meaning"],rows,[38*mm,132*mm]))

# ROADMAP: preserve the source implementation guide's seven phases and 43 numbered actions.
def build_roadmap():
    s=[]
    cover(s,"ROADMAP","From product idea to a testable proof of concept","A teaching guide to the sequence, decisions, gates, and outputs for a reusable medical-journal RAG assistant.")
    s += [title("Document control and scope"),P("This roadmap follows the seven-phase outline in <i>Ver 1 - Complete Implementation Guide for POC</i>. It preserves the Phase 1-7 names and the guide's numbered actions 1-43. The Master Guide supplies the broader product principles: evidence discovery, not diagnosis; citations from real sources; staged scope; article-type awareness; and measurable quality review."),callout("Current project status", "Phase 1 (Development Foundation) and Phase 2 (Data Acquisition / Define and Acquire the POC Corpus) have passed their project checkpoints. The selected corpus is the January 2025 issue. Phase 3 is the next implementation phase. A passing setup or corpus checkpoint is not proof of clinical accuracy."),title("Contents at a glance")]
    s += bullets(["1. The project: intended user, problem, and boundaries","2. Design principles that shape the sequence","3. Roadmap at a glance: Phases 1-7","4. Detailed numbered implementation sequence (1-43)","5. Phase gates, evidence, and change control","6. Reuse across journals and future expansion","7. Risks, anti-patterns, and learning approach","8. References and glossary"])
    s += section("1","The project: intended user, problem, and boundaries",[
        "The problem is information discovery across a large journal archive. A pediatric professional may know the clinical topic but not the exact article title, author, issue, or keyword. A literature assistant should help locate, compare, and understand what the selected journal has published.",
        "The assistant is designed as a domain-specific knowledge retrieval system. A question is interpreted, relevant journal material is retrieved, evidence is summarized, and the answer points back to articles. This is a RAG pattern: the model receives retrieved source passages at answer time rather than relying only on its pretrained memory.",
        "The initial POC is not an AI doctor. It must not diagnose, prescribe, replace clinical judgement, or imply evidence that is not in the selected corpus. It is a journal-literature navigation and synthesis prototype."])
    s += [title("1.1 Users and tasks",2),P("Primary users include pediatricians, residents, researchers, medical educators, and students. The initial tasks are topic search, evidence summary, article comparison, type-aware filtering, author or date lookup, and a safe no-answer response when the corpus is insufficient."),title("1.2 POC scope",2),P("The current POC is intentionally small: one issue, January 2025, Volume 62, Issue 1 of Indian Pediatrics, with the supplied local PDFs and a structured catalogue. This gives us different article forms without taking on the risks of bulk archive acquisition.")]
    s += section("2","Design principles that shape the sequence",[
        "These principles explain why later work depends on earlier preparation. The sequence is a quality-control strategy, not bureaucracy."])
    s += table(["Principle","Why it matters","Practical rule"],[
        ["Evidence before fluency","A fluent answer can still be unsupported.","Keep retrieved passages and citations available for every answer."],
        ["Metadata plus text","Semantic matching alone cannot reliably filter by author, year, volume, section, or type.","Model the article first; attach article metadata to every later text chunk."],
        ["Preserve source files","Processing errors must be recoverable and auditable.","Keep raw originals unchanged; create derived text elsewhere."],
        ["Small, staged corpus","A huge archive magnifies extraction, permission, and QA problems.","Prove the pipeline on a bounded issue before expansion."],
        ["Modular and reusable","A second journal should require new configuration and mapping, not a rewrite.","Separate shared processing logic from journal-specific settings and source adapters."],
        ["Explicit uncertainty","The system must be able to say the corpus does not answer a question.","Define a no-answer threshold and evaluate it intentionally."],
        ["Build only what is needed","Premature agent orchestration and infrastructure increase failure points.","Start with one transparent retrieval and generation workflow."]],[34*mm,58*mm,78*mm])
    s += section("3","Roadmap at a glance",["The Implementation Guide organizes the work into seven phases. Numbering below stays aligned to that guide. Names have been retained, with Step 1 and Step 2 also described using the labels adopted during this project."])
    s += table(["Phase","Phase name","Main outcome","Gate to next phase"],[
        ["Phase 1","Development Foundation / Set Up the Development Foundation","Reproducible local project, journal-neutral structure, settings, Git, startup and readiness check.","Step 1 checker passes; no unexplained failures."],
        ["Phase 2","Data Acquisition / Define and Acquire the POC Corpus","Issue scope, article catalogue, file manifest, exclusion decisions and corpus checkpoint.","Step 2 checker passes; source/use scope recorded."],
        ["Phase 3","Data Processing","Extract and clean PDF/HTML text; preserve structure and page provenance; inspect quality.","Representative files pass extraction and quality review."],
        ["Phase 4","RAG","Chunk, embed, index, retrieve, generate grounded answers and cite sources.","Retrieval, citation, and no-answer behavior demonstrated."],
        ["Phase 5","Application","Provide a basic interface and core search, answer, source, comparison and filtering workflows.","User can complete intended workflows reliably."],
        ["Phase 6","Validation","Build golden questions and evaluate retrieval, answers, citations, and safety.","Known defects fixed or recorded against stated targets."],
        ["Phase 7","Demonstration","Select demo questions, polish the prototype, prepare script and technical evidence.","POC V1 demo package is reviewable; limits disclosed."]],[18*mm,43*mm,61*mm,48*mm])
    s += [title("3.1 Dependency chain",2),P("The primary dependency is: requirements and project foundation -> controlled data -> metadata and quality -> retrieval -> grounded answers and citations -> user workflows -> validation -> demonstration. A later stage may reveal an earlier defect; the process must allow a controlled return to fix it.")]
    s += [title("4. Detailed numbered implementation sequence (1-43)")]
    phase_items=[
        ("Phase 1 - Development Foundation",[(1,"Set up Python environment"),(2,"Create Git repository"),(3,"Create reusable folder structure"),(4,"Install only the foundation packages needed"),(5,"Create safe environment-variable template"),(6,"Create application and journal configuration"),(7,"Provide optional LLM connection test when service credentials are approved"),(8,"Provide optional embedding connection test when service credentials are approved")]),
        ("Phase 2 - Data Acquisition",[(9,"Study January 2025 issue structure"),(10,"Create article_metadata.csv"),(11,"Identify usable articles and content roles"),(12,"Collect accessible article documents"),(13,"Store raw documents with traceable names and manifest")]),
        ("Phase 3 - Data Processing",[(14,"Extract PDF or HTML text"),(15,"Clean extraction artifacts without changing meaning"),(16,"Attach validated metadata"),(17,"Inspect extraction and metadata quality")]),
        ("Phase 4 - RAG",[(18,"Chunk documents by meaningful section"),(19,"Create embeddings"),(20,"Build and persist the vector/search index"),(21,"Implement retrieval"),(22,"Add hybrid keyword and semantic search"),(23,"Build grounded answer generation"),(24,"Create verified source citations"),(25,"Implement abstention / no-answer logic")]),
        ("Phase 5 - Application",[(26,"Build Streamlit POC interface"),(27,"Implement natural-language search"),(28,"Render the answer and key findings"),(29,"Show relevant source articles and links"),(30,"Support comparison workflow"),(31,"Filter by article type")]),
        ("Phase 6 - Validation",[(32,"Create the Golden Test Set"),(33,"Evaluate retrieval"),(34,"Evaluate answer correctness and grounding"),(35,"Evaluate citation validity"),(36,"Evaluate hallucination and no-answer behavior"),(37,"Fix and retest defects")]),
        ("Phase 7 - Demonstration",[(38,"Select 5-7 demonstration questions"),(39,"Polish interface for the intended audience"),(40,"Prepare a reproducible demonstration script"),(41,"Prepare the technical manual"),(42,"Prepare the POC test report"),(43,"Declare POC V1 ready only against explicit criteria")])]
    for phase,items in phase_items:
        s += [title(phase,2)]
        for n,desc in items:
            s.append(P(f"<b>{n}. {desc}.</b> Define the input, execute the task, capture the output and verify it before relying on it in the next step."))
    s += section("5","Phase gates, evidence, and change control",[
        "A gate is a documented decision that the next phase has the prerequisites it needs. A gate does not mean that the whole product is correct. Record what was checked, the result, warnings, unresolved assumptions, and the exact follow-up owner/action."])
    s += table(["Gate","Evidence to retain","Stop and fix when..."],[
        ["Phase 1","Environment notes, configuration, folder tree, Git root, startup output, checker result.","The app cannot start predictably, required paths/config fail, or secret handling is unsafe."],
        ["Phase 2","Issue source URL, catalogue, file manifest, scope/exclusion notes, acquisition basis, checker output.","Files are untraceable, article IDs duplicate, required fields fail, or scope/access basis is unclear."],
        ["Phase 3","Extracted text samples, page/section mapping, issue log, QA decisions.","Titles/pages are mismatched, text is missing or corrupted, or article boundaries are wrong."],
        ["Phase 4","Retrieval examples, chunks and source links, citation checks, answer/no-answer logs.","Answers cannot be traced to retrieved evidence or the system invents support."],
        ["Phase 5-7","Workflow walkthrough, Golden Test Set results, demo checklist/report.","Critical defects remain hidden or claims exceed evaluation evidence."]],[25*mm,70*mm,75*mm])
    s += [title("5.1 Decision log template",2),*table(["Field","Record"],[["Decision ID and date","Unique entry and date of change."],["Question","What choice had to be made?"],["Options considered","Include viable alternatives, not every imaginable option."],["Choice and rationale","What was selected and why?"],["Trade-offs / risks","What capability or assurance is limited?"],["Evidence / approval","Link to source, checker, user decision, or permission review."],["Revisit trigger","What new fact would justify changing the decision?"]],[45*mm,125*mm])]
    s += section("6","Reuse across journals and future expansion",[
        "The product is being designed as a reusable template. The shared application should not assume every journal has the same website, PDF layout, section vocabulary, publication cadence, or reuse terms. The first journal-specific configuration describes identity and source URLs; future journal onboarding adds a source adapter or parsing rules when needed."])
    s += table(["Shared across journals","Configured per journal","Validated per new journal"],[
        ["Article/chunk data model, provenance fields, checker patterns, retrieval interfaces, citation representation, safety behavior.","Journal ID/name, issue URLs, section mappings, publication calendar, access status, corpus selection.","Website structure, PDF layouts, article-type vocabulary, author formatting, access conditions, extraction quality and search behavior."]],[55*mm,55*mm,60*mm])
    s += [title("6.1 Portability test",2),P("A genuinely reusable system can add a second journal without editing Indian Pediatrics assumptions throughout the core. The test is: create a journal configuration from the example template, acquire a small permitted corpus, map that journal's sections, pass data checks, and run the same retrieval/evaluation contract. If core code requires many journal-name conditionals, separate the journal-specific rule into configuration or an adapter.")]
    s += section("7","Risks, anti-patterns, and learning approach",[
        "The common temptation is to begin with a chat screen because it feels like visible progress. In this project, the less visible work - scope, source identity, metadata, text quality and evaluation - determines whether answers can be trusted."])
    s += table(["Avoid","Why it fails","Safer practice"],[
        ["Download the entire archive at once","Scale hides rights issues and multiplies OCR/metadata defects.","Start with one issue and expand only after measured success."],
        ["Treat every PDF as a clinical paper","Notices, news, duplicates and clippings do not have the same evidence value.","Assign content roles and retrieval eligibility."],
        ["Use filenames as IDs","Page-number filenames are ambiguous and changeable.","Assign persistent article IDs; store original filenames separately."],
        ["Use embeddings as the complete search solution","Exact author/title/year searches and filters can fail in pure vector search.","Combine semantic, lexical, metadata filters and reranking."],
        ["Let the language model create citations","The model may fabricate bibliographic details.","Build citations from retrieved record fields and verify links."],
        ["Add autonomous agents before a reliable baseline","More moving parts complicate debugging and evaluation.","First deliver one inspectable RAG workflow."],
        ["Claim clinical validation from a demo","A small journal corpus and informal review do not establish clinical safety.","Call it a literature POC; document scope and evaluation limits."]],[43*mm,60*mm,67*mm])
    s += section("8","References and glossary",["The roadmap is aligned to the project documents and current implementation records listed below. Where the old planning documents differ from the project as actually built, this manual describes the current project state and calls out the difference rather than silently copying stale values."])
    s += bullets(["Ver 1 - Master Guide for POC.pdf: product rationale, scope, RAG principles, quality targets, and the 43-step high-level flow.","Ver 1 - Complete Implementation Guide for POC.pdf: seven implementation phases and 43 numbered implementation actions.","Ver 1 - Implementation - Step 1.pdf: detailed legacy environment setup example; some paths, Python versions, and API-check expectations differ from the current project.","Current Project README.md, config files, scripts/check_step1.py, scripts/check_step2.py, and Step 2 metadata/checkpoint records."])
    add_glossary(s,[["RAG","Retrieval-Augmented Generation: retrieve source evidence and provide it to a language model for a grounded response."],["Corpus","The bounded set of source documents selected for an application or experiment."],["Metadata","Structured facts describing an article, such as title, author, date, issue, pages and type."],["Gate","A checkpoint that confirms prerequisites and makes unresolved issues visible."],["Abstention","A deliberate response that says evidence is insufficient or absent."],["Golden Test Set","Questions with expected relevant sources/findings, used to test system behavior."],["POC","Proof of Concept: a limited demonstration that an idea can work under stated conditions."]])
    make_pdf("Roadmap.pdf","Roadmap | Phases 1-7",s)

def build_step1():
    s=[]
    cover(s,"STEP 1","Set Up the Development Foundation","A beginner's implementation chapter: make the project reproducible, journal-neutral, safe to extend, and easy to check before acquiring content.")
    s += [title("Document control and alignment"),P("This chapter follows <b>Phase 1 - Development Foundation</b> in the roadmap and the project-approved Step 1 label, <b>Set Up the Development Foundation</b>. The legacy Step 1 PDF is used as a learning reference, but the actual implementation here uses the current Project folder, current Python runtime, journal TOML files, and a lightweight foundation rather than claiming every legacy API/UI item was delivered."),P("Target workspace: <b>D:\\AAAA Pediatric Assistant\\AI Asst for IP\\Project</b>. This path is authoritative for current work. The folder is nested under the supplied AI Asst for IP directory."),callout("Step 1 outcome", "A new developer can identify the project root, create or use an isolated Python environment, load a journal-specific configuration through shared code, run a local startup check, and verify the foundation using one repeatable checker."),title("Contents at a glance")]
    s += bullets(["1. Purpose, prerequisites, and acceptance criteria","2. Decisions: stack, modularity, and journal reuse","3. Project layout and the role of each file","4. Reproduce the environment on Windows","5. Configuration and journal separation","6. Startup behavior and safe secret handling","7. Step 1 readiness checkpoint","8. Troubleshooting, teaching exercises, and handoff"])
    s += section("1","Purpose, prerequisites, and acceptance criteria",[
        "Step 1 turns a product idea into an executable software workspace. It establishes names, boundaries, configuration, reproducibility, and a basic program entry point. Its output is deliberately boring: a clean start and clear project organization. That boring foundation lowers the cost of every later change.",
        "This phase does not acquire or process article content, create embeddings, build a vector database, call an LLM, or implement the final UI. Those belong to later phases. Avoid reporting a successful startup as proof that RAG works."])
    s += [title("1.1 Learner outcomes",2)] + bullets(["Explain why a virtual environment isolates project packages.","Locate shared application logic separately from journal-specific settings.","Run configuration loading and the startup smoke check.","Explain why an example environment file is different from a private .env file.","Read a readiness report and distinguish failure from warning.","Recognize the difference between a template that is reusable and one that merely has a generic name."])
    s += [title("1.2 Step 1 acceptance criteria",2),*table(["Criterion","How the project checks it","Interpretation"],[
        ["Python version","Checker confirms >= 3.11.","Python 3.12 is current development target; a bundled runtime is not a portable project requirement."],
        ["Project environment","Checker verifies interpreter runs from Project/.venv.","Avoid installing dependencies globally or into another project."],
        ["Reusable structure","Required config, data, source, scripts, tests and evaluation directories exist.","Structure reserves clear homes for future phases."],
        ["Foundation files","README, pyproject, requirements, .env.example and config files exist.","A second developer can understand and reproduce the foundation."],
        ["Configuration","Indian Pediatrics TOML loads and identifies issue 766.","This is configuration validation, not a permission grant."],
        ["Git root","The repository root is the Project folder.","Version history should apply to the application workspace."],
        ["Startup smoke check","Local entry point prints READY and exits successfully.","Tests that imports/config/start path work; not an AI answer test."],
        ["Warnings visible","Unconfirmed full-text terms are reported as warnings.","Warnings are tracked for appropriate later decisions."]],[34*mm,61*mm,75*mm])]
    s += section("2","Decisions: stack, modularity, and journal reuse",[
        "Choose the smallest set of tools that supports the current phase. Technology choices are provisional architecture decisions; they should be revisited when requirements or evidence change."])
    s += table(["Choice","Why it fits now","Why not add more now"],[
        ["Python 3.11+ (3.12 target)","Strong ecosystem for document processing, search, AI APIs and Windows development.","The foundation currently needs only standard-library capabilities; no package pile is required."],
        ["PowerShell for Windows instructions","Native shell for the target platform and existing user environment.","Avoid relying on Unix-only commands."],
        ["Git at Project root","Change history and rollback for source and configuration.","A remote GitHub setup is not a prerequisite unless explicitly approved and configured."],
        ["TOML configuration","Readable, standard-library parsing, suitable for journal/app settings.","Avoid duplicating a setting in source code and config."],
        ["Standard-library startup module","Keeps Phase 1 install simple, reproducible and quick to check.","No need yet for FastAPI, Streamlit, LangChain, Chroma, pandas, PDF libraries or model SDKs."],
        ["Shared src package + per-journal config","Separates generic workflow code from each journal's identity and URLs.","Do not fork the whole codebase for each journal."],
        ["Local file data folders","Keep raw, processed, indexes and cache distinct; make provenance visible.","Do not place source PDFs in Python module folders."]],[34*mm,67*mm,69*mm])
    s += [title("2.1 Why defer the LLM, embedding, and UI connections?",2),P("At this step there is no defined prompt, evidence retrieval behavior, or user workflow to test. Installing AI packages or configuring paid API credentials now increases setup complexity without validating journal retrieval. The project keeps `.env.example` and configuration paths ready for later, but its current readiness checker expects no third-party packages for the foundation."),title("2.2 Reuse model",2),P("The shared package belongs in `src/journal_assistant/`; journal-specific facts belong in `config/journals/<journal_id>.toml`. The example template demonstrates the fields expected for another journal. Where websites differ substantially, later work should implement a separate source adapter rather than adding journal-specific assumptions throughout shared code.")]
    s += section("3","Project layout and the role of each file",["The actual structure is designed to grow in phases. Empty folders with a `.gitkeep` are intentional: Git does not retain empty directories, but the folders communicate planned boundaries."])
    s += table(["Path","Purpose now","Future use / guardrail"],[
        ["config/app.toml","Application-wide defaults.","Shared settings; avoid journal-specific facts here."],
        ["config/journals/indian_pediatrics.toml","Journal identity, URLs, selected issue, access review status.","One file per authorized journal; keep rights status explicit."],
        ["config/journals/journal_template.toml.example","Reusable configuration template.","Copy and complete for another journal; do not leave placeholder values in an active config."],
        ["src/journal_assistant/","Shared configuration loader and startup logic.","Reusable application code; keep user interface and journal data separate."],
        ["scripts/run_app.py","Local foundation entry point.","Later scripts for ingestion and checks can be added here."],
        ["scripts/check_step1.py","Automated readiness checks for Step 1.","Keep checks repeatable, clear, and low-risk."],
        ["scripts/check_step2.py and scripts/prepare_step2_metadata.py","Step 2 corpus catalogue and checkpoint support.","Step-specific utilities; later add migration/version handling if schema changes."],
        ["data/raw/","Original PDFs supplied for the POC.","Treat as immutable; verify provenance; ignored by Git by default."],
        ["data/metadata/","Article catalogue, manifest, checkpoint notes.","Structured records are the bridge between files and retrieved evidence."],
        ["data/processed/","Reserved for derived text and cleaned documents.","Never overwrite the originals here."],
        ["data/indexes/ and data/cache/","Reserved for generated search artefacts.","Usually reproducible and excluded from source control."],
        ["tests/ and evaluation/","Reserved for software tests and answer/retrieval evaluation.","Do not confuse code tests with evidence-quality evaluation."],
        [".env.example / .gitignore","Variable names and ignored local/secret/generated files.","Never store live keys in the example file or commit a local .env."]],[45*mm,60*mm,65*mm])
    s += [title("3.1 Generic journal onboarding checklist",2)] + bullets(["Choose a stable journal ID (lowercase underscore or hyphen form).","Copy the journal template; add display name, website, issue-index URL, selected issue metadata, and access-review status.","Record site structure and section terms in a source note; do not assume the source has Indian Pediatrics' structure.","Verify each source URL and a small authorized document sample before adapting parsers.","Run the foundation check with the new config selected, then add journal-specific acquisition checks later.","Keep shared code journal-neutral; record any necessary source-specific parsing adapter as an explicit module."])
    s += section("4","Reproduce the environment on Windows",[
        "Use Windows PowerShell opened in the Project root. The README is the current source of setup commands. A machine-specific bundled Python runtime was used to create the current environment; students should use their own supported Python installation rather than copying that machine path."])
    s += [P("<b>From the Project folder:</b>"),P("py -3 -m venv .venv<br/>.\\.venv\\Scripts\\Activate.ps1<br/>python --version<br/>python -m pip --version<br/>python -m pip install -r requirements.txt", "Calloutx"),P("The current Step 1 `requirements.txt` contains no third-party dependencies. This is intentional. The activation command changes the active shell environment; the checker independently validates that Python is executing from the project's `.venv`. If activation scripts are disabled by local policy, follow the organization's approved PowerShell approach rather than bypassing security settings.")]
    s += [title("4.1 Dependency discipline",2)] + bullets(["Add a package only when a phase needs it; record it in the project dependency declaration.","Use the project's active interpreter to install packages so they do not land in an unrelated Python.","When adding runtime packages, pin or constrain versions according to the team's reproducibility policy and verify imports.","Do not copy `pip freeze` wholesale without review if it captures unrelated environment packages.","Never put credentials in install commands, scripts, notebooks, screenshots or documentation."])
    s += section("5","Configuration and journal separation",[
        "Configuration is data that controls behavior without changing reusable code. TOML is used because it is readable and parsed by Python's standard library. The loader validates expected fields and makes an invalid config fail visibly rather than letting a later operation use wrong source settings."])
    s += table(["Configuration area","Example fields","Validation question"],[
        ["Application","shared defaults and selected config pointer","Are defaults independent of a specific journal?"],
        ["Journal identity","journal_id, display_name, homepage and issue URLs","Do URLs lead to the intended publisher and index?"],
        ["Initial corpus","title, issue_id, date, volume, issue number","Does this match the selected issue listing?"],
        ["Access review","review_status and full_text_permission","Does it report only what has actually been reviewed?"],
        ["Example template","placeholder identity and expected fields","Can a second journal owner fill this in without editing source code?"]],[36*mm,68*mm,66*mm])
    s += [title("5.1 Secrets are not journal metadata",2),P("The `.env.example` file is a safe template and may contain names such as an API variable without a real secret value. A private `.env` is local and must be excluded from Git. Journal source URLs and permission statuses belong in journal configuration; API tokens belong in private environment variables or a managed secret store. Never conflate having a working API key with permission to process copyrighted journal text.")]
    s += section("6","Startup behavior and safe secret handling",[
        "The foundation runner loads configuration and returns a clear readiness indication. It is deliberately not a chatbot: no model call, embedding request, retrieval, or PDF extraction is implied by the word `READY`. The small entry point gives later modules a stable place from which to grow."])
    s += [title("6.1 What a smoke check proves",2)] + bullets(["The Python interpreter is usable.","The expected configuration file can be found, parsed, and validated.","The package imports and local startup code execute without an exception.","The Project root and required foundation files can be identified."])
    s += [title("6.2 What it does not prove",2)] + bullets(["That the source website is reachable now.","That the PDFs are permission-cleared for every use.","That extraction preserves article meaning.","That a vector database or language model works.","That answers are medically accurate, clinically safe, or validated."])
    s += section("7","Step 1 readiness checkpoint",[
        "Run the checker from the active Project virtual environment. Its pass/fail output is the evidence for the foundation gate; keep the final output with the implementation notes when repeating setup on a new computer."])
    s += [P("python scripts\\check_step1.py", "Calloutx"),*table(["Checker group","What it checks","How to respond"],[
        ["Runtime","Supported Python and active Project .venv.","Activate the correct environment or recreate it."],
        ["Structure and required files","Expected directories and foundation files exist.","Create the missing item from project instructions; do not work around by weakening the check."],
        ["Journal configuration","The selected Indian Pediatrics config loads and names issue 766.","Correct TOML or choose the intended configuration file."],
        ["Project metadata and dependencies","TOML metadata is valid and Step 1 requirements are intentionally empty.","Keep dependency list phase-appropriate."],
        ["Git root","Git repository top directory equals Project.","Initialize or repair repository from the intended root."],
        ["Startup smoke test","Entry point exits successfully and prints READY.","Inspect captured error output and fix the cause."],
        ["Access-review warning","Unconfirmed full-text status is visible.","Track this honestly in corpus collection and external-use decisions."]],[35*mm,72*mm,63*mm])]
    s += [title("7.1 Recorded result for this project",2),P("The Step 1 checkpoint previously reported <b>9 passed, 0 failed, 1 warning</b>. The warning was the journal configuration's pending confirmation for full-text access/indexing. It was a warning rather than a foundation failure: Step 1 establishes software readiness, while content rights and corpus scope are handled explicitly in Step 2. The user later supplied local files and stated access for the internal POC; that statement is recorded as the acquisition basis, not as a general publisher licence.")]
    s += section("8","Troubleshooting, teaching exercises, and handoff",[
        "Troubleshooting should start from the first failing line, not from reinstalling every package. Use the checker as a diagnostic map, read its specific label, and repair the underlying cause."])
    s += table(["Symptom","Likely cause","First check"],[
        ["Python version fails","Older or unexpected Python is on PATH.","Run `python --version` and `Get-Command python`; create `.venv` using intended interpreter."],
        ["Virtual environment fails","Shell is using global Python or another project's env.","Activate `.venv` and inspect `python -c \"import sys; print(sys.prefix)\"`."],
        ["TOML fails to load","Syntax error, wrong path, or required value absent.","Inspect exact TOML file, quotes, sections, and configured path."],
        ["Git root is wrong","Repository was initialized in parent or nested directory.","Inspect `git rev-parse --show-toplevel`; do not silently add the parent workspace."],
        ["Startup does not print READY","Import/config error or unexpected app state.","Run the runner directly and read full traceback before changing code."],
        ["Access warning appears","Permission field still unconfirmed.","Keep warning visible and record the user's stated basis and restrictions; do not change status to approved without evidence."]],[40*mm,57*mm,73*mm])
    s += [title("8.1 Student exercises",2)] + bullets(["Draw the dependency graph from PowerShell and virtual environment to configuration loader and startup check.","Create a second journal TOML by copying the example. Identify which fields are generic and which are journal-specific.","Intentionally break a configuration key in a disposable copy and observe the check failure; restore it and rerun.","Explain in your own words why a green startup check cannot establish clinical accuracy.","Propose a new readiness assertion and state what failure it should catch without overclaiming."])
    s += [title("8.2 Handoff to Phase 2",2),P("Before Phase 2, the workspace should be stable and the selected journal configuration should identify the intended issue. Phase 2 defines the corpus and acquires or inventories source documents. Do not begin chunking or embeddings merely because PDFs have been placed in `data/raw/`; first catalogue them and record role, source, acquisition status, and exclusions.")]
    s += [title("References and glossary",1)] + bullets(["Ver 1 - Implementation - Step 1.pdf (legacy detailed setup reference; its old path/runtime and API tests are not current project facts).","Current Project README.md, pyproject.toml, requirements.txt, config/journals/indian_pediatrics.toml, scripts/check_step1.py and scripts/run_app.py.","Ver 1 - Complete Implementation Guide for POC.pdf, Phase 1 Development Foundation."])
    add_glossary(s,[["Virtual environment","A project-specific Python installation area for isolating packages."],["Configuration","Settings stored outside reusable program logic."],["Smoke check","A short run that verifies basic startup, not full correctness."],["Journal adapter","A module handling source-specific structure while keeping shared workflows reusable."],["Secret","Credential or token that must not be committed or exposed."],["Git repository root","The top-level directory whose files are tracked by that repository."]])
    make_pdf("Step1.pdf","Step 1 | Development Foundation",s)

def build_step2():
    s=[]
    cover(s,"STEP 2","Define and Acquire the POC Corpus","A practical guide to issue scoping, article records, file provenance, content roles, exclusions, permission notes, and a repeatable corpus checkpoint.")
    s += [title("Document control and alignment"),P("This chapter follows <b>Phase 2 - Data Acquisition</b> and the project-approved Step 2 label, <b>Define and Acquire the POC Corpus</b>. The selected source is January 2025, Volume 62, Issue 1 of Indian Pediatrics, issue ID 766. The official issue page is <link href='https://indianpediatrics.net/articles.php?issue=766' color='#147D83'>https://indianpediatrics.net/articles.php?issue=766</link>. This chapter documents inventory and acquisition only; it does not perform Phase 3 extraction, cleaning or quality correction."),callout("Step 2 accepted scope", "The user approved using the supplied local PDFs for an internal POC and explicitly chose to scope out the two unavailable Correspondence PDFs on pages 81-82. The catalogue preserves those issue entries with a scoped_out status so omission is visible."),title("Contents at a glance")]
    s += bullets(["1. What corpus acquisition means","2. Scope the issue and define inclusion roles","3. Article metadata model and retrieval needs","4. Inventory and provenance of the supplied PDFs","5. Classification, inclusion, and exclusions","6. Step 2 implementation walkthrough","7. Checkpoint design and recorded result","8. Permissions, risks, and what to avoid","9. Reuse this process for another journal","10. Handoff into Phase 3"])
    s += section("1","What corpus acquisition means",[
        "A corpus is the bounded set of documents from which the assistant may retrieve evidence. Corpus acquisition is more than copying files into a folder. A reliable acquisition step answers: which issue, which article records, which local files, which are usable for clinical retrieval, where each came from, what remains absent, and what use basis is recorded.",
        "The publisher issue listing is the catalogue authority for the issue structure. Local PDFs are the acquired file artifacts. Article IDs connect catalogue records to file records now and will later connect extracted text, chunks, embeddings, citations, and evaluation cases. A filename such as `15.pdf` is only a physical filename, not a durable article identity."])
    s += [title("1.1 Current source and selected issue",2),*table(["Field","Selected value"],[
        ["Journal","Indian Pediatrics"],["Issue","January 2025, Volume 62, Issue 1"],["Publisher issue ID","766"],["Publication date in project configuration","2025-01-15"],["Official contents page","https://indianpediatrics.net/articles.php?issue=766"],["Local corpus folder","Project/data/raw/2025_Jan"],["Current file count","19 PDF files"]],[50*mm,120*mm])]
    s += section("2","Scope the issue and define inclusion roles",[
        "Before processing files, define what counts as an item and how different materials should be treated. An issue may contain original studies, reviews, clinical case material, invited commentaries, educational articles, clippings, news, notices, corrections, and advertisements. These have different evidentiary value and user intent."])
    s += table(["Content role","Default POC behavior","Reason"],[
        ["clinical_evidence","Include in clinical evidence retrieval when article record and text pass later QA.","Primary studies, systematic reviews or guideline summaries may answer clinical-literature questions, but preserve study design and limitations."],
        ["clinical_context","May retrieve as contextual material with section and type shown.","Commentaries and perspective pieces are not equivalent to primary research."],
        ["nonclinical_context","Catalogue; exclude from clinical answers unless a separate task explicitly calls for it.","Medical education content is relevant to education questions, not treatment evidence."],
        ["secondary_source","Retain with reduced ranking and clearly labelled secondary status.","Clippings summarize a separate paper; cite both the clipping and its cited original when available."],
        ["administrative_news / notice / advertisement","Catalogue or ignore for clinical evidence; exclude from clinical retrieval.","They are not clinical studies and can produce misleading retrieval matches."],
        ["duplicate_or_mixed","Keep in audit manifest; do not index duplicate or administrative portions as article evidence.","Avoid duplicate weighting and contaminated chunks."],
        ["scoped_out / unavailable","Retain a catalogue entry with status and reason; no local full text.","Transparent scope is better than silently pretending the issue is complete."]],[38*mm,70*mm,62*mm])
    s += [title("2.1 Inclusion decisions are use-case specific",2),P("A commentary may be useful for a question such as 'what perspectives did the journal publish?' while being inappropriate as sole support for a treatment recommendation. A medical education article may be valuable to an educator but not to clinical evidence synthesis. Store stable classifications first, then let each retrieval task define allowed or preferred roles.")]
    s += section("3","Article metadata model and retrieval needs",[
        "The article catalogue provides an index for both semantic retrieval and deterministic search. Search by author, issue, year, article type, or date should not depend on an embedding model guessing these facts from prose."])
    s += table(["Metadata group","Fields in the current catalogue","Retrieval or audit purpose"],[
        ["Identity","article_id, title, journal, issue_id","Stable citations, title lookup, de-duplication and parent-child linking."],
        ["People","authors","Author search and disambiguation; blanks mean not yet verified, not 'no authors'."],
        ["Publication","publication_date, year, month, volume, issue_number, page_start, page_end","Date ranges, chronology, issue filters and citation display."],
        ["Classification","section, content_role","Article type filtering, evidence-aware ranking and role-specific workflows."],
        ["Source/provenance","publisher_issue_url, local_filename, access_basis","Trace every record back to source listing and local artifact."],
        ["Acquisition/use","acquisition_status, external_demo_permission, notes","Identify available, scoped-out and permission-review state."],
        ["Future enrichment","DOI, abstract, keywords, study design, population, topic terms","Improves exact search, evidence filtering and query facets after verification."]],[31*mm,70*mm,69*mm])
    s += [title("3.1 Stable identifier pattern",2),P("Current IDs use `IP-2025-V62-I01-###`. Components identify the journal, year, volume, issue, and sequence. Do not derive identity only from a page number: corrections, supplements, multipart articles or renamed files can change page-level conventions. Store the original PDF filename separately."),title("3.2 Metadata quality rules",2)] + bullets(["Use the publisher's title and section where available; preserve original capitalization if citation rules need it.","Keep a field blank if it has not been verified; do not infer authors, DOI, pages or study design from a filename.","Represent unknown, not applicable, and unavailable as distinct concepts where the data model needs the difference.","Store raw/source metadata separately from normalized values if normalization can discard meaningful original form.","Use controlled content-role values consistently, with definitions in the project notes.","Add topics and keywords only after a documented classification or extraction process; do not turn guesses into authoritative facets."])
    s += section("4","Inventory and provenance of the supplied PDFs",[
        "Nineteen physical PDFs were present in `data/raw/2025_Jan`. Before any extraction, the inventory recorded filenames, relative paths, sizes, physical page counts, and whether any selectable text could be extracted. Basic signature and nonempty-file checks reduce the risk of indexing a mislabeled or empty file. These checks do not prove that every page is complete or that OCR quality is good."])
    s += [title("4.1 File-to-record mapping",2),*table(["Local file(s)","Mapped item / pages","Treatment in this POC"],[
        ["9.pdf","President's Page, p. 9","Catalogue as context; retrieval eligibility depends on task."],
        ["11.pdf","Invited Commentary, pp. 11-12","Context, labelled commentary."],
        ["13.pdf","Invited Commentary, pp. 13-14","Context, primary local copy for this article."],
        ["14.pdf","Repeated ending from p. 14 plus access notice","Exclude from text ingestion; duplicate/admin mixed file."],
        ["15.pdf, 21.pdf, 27.pdf, 31.pdf, 37.pdf, 44.pdf, 49.pdf","Original Articles, pp. 15-52","Clinical evidence candidate; later extraction and QA required."],
        ["53.pdf","Research Letter, pp. 53-55","Clinical evidence candidate; preserve article type."],
        ["56.pdf","Systematic Review, pp. 56-62; PDF includes unpaginated supplemental material","Clinical evidence candidate; page and supplement boundaries need Phase 3 QA."],
        ["63.pdf","Medical Education, pp. 63-70","Nonclinical context; not clinical answer evidence by default."],
        ["71.pdf","Update/guideline synopsis, pp. 71-74","Clinical evidence candidate; label as a synopsis of an external guideline."],
        ["75.pdf","Reminiscences, pp. 75-77","Historical/context record; not a primary clinical study."],
        ["78.pdf","Clinical Case Letter, pp. 78-80","Clinical case evidence; distinguish case-level report from general evidence."],
        ["81.pdf and 82.pdf","Two issue-listed Correspondence items","Not supplied; user-approved scoped_out in catalogue."],
        ["83.pdf","Clippings: Neonatology","Secondary-source item; limited ranking; preserve cited original study."],
        ["84.pdf","News in Brief","Catalogue/audit only; exclude from clinical retrieval."]],[34*mm,65*mm,71*mm])]
    s += [title("4.2 Important distinction: physical PDFs versus issue contents",2),P("The folder contains 19 PDF files, but that count is not the same as the number of issue entries or the number of documents safe for clinical retrieval. One file repeats content and adds a notice, two issue-listed items are absent, and one supplied file is a news item. The manifest therefore tracks each physical file while the article catalogue tracks editorial entries. Those are separate tables because one source file can be mixed, duplicate, or missing.")]
    s += section("5","Classification, inclusion, and exclusions",[
        "The catalogue is intentionally broader than the clinical retrieval set. This preserves issue coverage and makes exclusions reviewable without allowing every item to influence a clinical answer."])
    s += [title("5.1 Current decisions",2)] + bullets(["Use 19 catalogue rows for the 19 substantive issue entries represented in this POC catalogue: 16 supplied article records, two issue-listed Correspondence records, and one Clippings record. The two Correspondence entries are explicitly `scoped_out`.","Track all 19 supplied PDFs in the manifest even where a PDF is nonclinical or excluded.","Exclude `14.pdf` because its content repeats the end of `13.pdf` and includes an access notice.","Exclude `84.pdf` News in Brief from clinical evidence retrieval.","Give `83.pdf` Clippings limited retrieval priority and preserve the cited external paper bibliographic details.","Keep role labels for commentaries, reminiscences, medical education and cases so the answer layer can distinguish evidence types.","Record user-provided local copies as the access basis for internal POC. Keep external/editor permission status separately pending confirmation."])
    s += [title("5.2 Why not delete excluded files?",2),P("An excluded item can still be valuable audit evidence. Keeping a file manifest entry explains what was examined and why it did not enter the clinical retrieval set. The raw file remains unchanged; selection is represented by metadata and later ingestion filters. Deleting source artifacts would make the decision harder to reproduce and might destroy useful provenance.")]
    s += section("6","Step 2 implementation walkthrough",[
        "The workflow has distinct actions. For another journal, repeat the sequence but adapt the source catalogue and local acquisition method rather than assuming the same URLs, file names, or categories."])
    s += table(["Action","What to do","Why / evidence produced"],[
        ["1. Confirm journal and issue","Record journal, publisher URL, issue ID/date/volume/number.","Creates a fixed scope and source citation."],
        ["2. Read issue contents","List all sections, articles, pages, authors where available, and non-article content.","Issue completeness can be checked independently of downloads."],
        ["3. Set role policy","Define clinical, contextual, secondary, administrative, duplicate and out-of-scope treatment.","Stops the RAG from treating unlike materials as equal evidence."],
        ["4. Assign IDs","Allocate stable article IDs once; never use filenames as the canonical key.","Enables parent-child links for text and chunks later."],
        ["5. Inventory files","Compare the directory to a manifest; record bytes/pages/text availability.","Detects missing, extra, empty or misidentified files."],
        ["6. Record access basis","Record source and user's asserted access/use scope; leave external reuse status explicit.","Prevents a local file from being mistaken for unrestricted permission."],
        ["7. Generate catalogues","Write article metadata and file manifest as UTF-8 CSV with stable column names.","Creates machine-readable inputs for later processing."],
        ["8. Run checkpoint","Check schemas, IDs, file match, signatures, text flags, exclusions and scope decisions.","Creates an objective gate before extraction begins."]],[31*mm,68*mm,71*mm])
    s += [title("6.1 Why two CSVs?",2),P("`article_metadata.csv` describes the journal's editorial items. `corpus_file_manifest.csv` describes physical local files. One article may be represented by multiple files; one file may contain a duplicate page or notice; and a catalogue entry may not have a supplied file. Combining these facts into one flat sheet encourages duplicate records and ambiguous status. The two tables connect through `article_id` where a relationship exists.")]
    s += [title("6.2 Preparation utility",2),P("`scripts/prepare_step2_metadata.py` is a repeatable generator for the current one-issue catalogue and manifest. Its issue records are explicit source data; its manifest scan checks the live PDF directory and uses PDF parsing to record physical page count and presence of selectable text. If issue scope, schemas, or source metadata changes, update the controlled source records and regenerate the CSVs, then review the diff. Avoid silently hand-editing generated output because regeneration could erase the change.")]
    s += section("7","Checkpoint design and recorded result",[
        "The checkpoint does not ask whether the final AI assistant is good. It asks whether the selected source set is accurately described and ready to be passed to extraction. The checker is intentionally deterministic and does not call an LLM."])
    s += table(["Check","Pass condition","Recorded result"],[
        ["Catalogue schema","Required columns exist and required values are filled.","PASS"],
        ["Stable IDs","19 unique catalogue IDs are present.","PASS"],
        ["Physical inventory","Manifest names match exactly the 19 PDFs in the source folder.","PASS"],
        ["File basics","Each manifest file exists, is nonempty, and begins with a PDF signature.","PASS"],
        ["Text availability","Selectable text was recorded for every supplied PDF.","PASS; quality and completeness still need Phase 3 review."],
        ["Scope gaps","Two unavailable Correspondence entries are explicitly `scoped_out`.","PASS, based on user's decision."],
        ["Nonclinical/mixed exclusions","News and duplicate/notice are excluded; clipping is limited.","PASS"],
        ["Permission reminder","External/editor reuse remains a visible warning.","WARN; not a corpus-structure failure."]],[40*mm,82*mm,48*mm])
    s += [title("7.1 Re-run the checkpoint",2),P("From the Project root, with Python available:"),P("python scripts\\prepare_step2_metadata.py<br/>python scripts\\check_step2.py", "Calloutx"),P("The checker currently reports <b>9 PASS, 0 FAIL, 1 WARN - READY FOR STEP 3</b>. The warning does not block internal POC preparation under the user's stated scope; it records that external redistribution/product use requires publisher/editor confirmation. A green Step 2 result means files and decisions are catalogued, not that they are text-clean, legally cleared for any use, or clinically validated.")]
    s += section("8","Permissions, risks, and what to avoid",[
        "The application must preserve a distinction among public page visibility, user access to a file, permission to download/process it, permission to show it in a demonstration, and permission to redistribute or commercialize it. A URL does not establish all of these. The project records the user's stated local access and intended POC use, while leaving external/editor permission confirmation visible."])
    s += table(["Risk / anti-pattern","Why it matters","Control in this project"],[
        ["Assume online availability means public-domain reuse","Access terms and reuse rights are not interchangeable.","Record access basis and external permission separately; seek editor/publisher confirmation for external use."],
        ["Index the whole issue without content-role filtering","News, ads, duplicate text or commentary can be misrepresented as clinical evidence.","Use role labels and explicit retrieval eligibility."],
        ["Trust filename order","Numbers may be page numbers, IDs, or arbitrary download names.","Use stable article IDs plus a separate filename mapping."],
        ["Mark a missing document as present because its catalogue entry exists","The AI could cite a source with no retrieved text.","Use `scoped_out` and no file association; retrieval must operate only on available content."],
        ["Treat selectable text as high-quality extraction","Selectable text may still omit columns, tables, figures, symbols or page order.","Phase 3 must inspect and compare extracted samples to rendered pages."],
        ["Trust blank metadata as a negative fact","Blank authors/DOI mean unknown or not yet verified.","Keep blanks explicit and add validation status in enrichment."],
        ["Publish raw PDFs with the demo code","Local access for a POC is not a redistribution grant.","Keep source PDFs local/ignored by Git and use permitted citation links in the demo."]],[43*mm,64*mm,63*mm])
    s += section("9","Reuse this process for another journal",[
        "A journal onboarding packet should be repeatable. Start from the generic journal config and metadata schema, but let source inspection determine the adapter and categories. Reuse the process, not the assumption that every journal has the same HTML, PDF structure, publication cadence or copyright terms."])
    s += [title("9.1 New-journal onboarding template",2)] + bullets(["Create journal identity/config and record the publisher source pages.","Document how to navigate decades, years, months, issues, and article detail pages.","Capture the publisher's category names and map them to the project's controlled content roles.","Select a small issue with accessible, representative content; record why it is suitable.","Confirm the basis for collecting and processing local documents before acquisition.","Create a stable journal-specific ID prefix while keeping the shared metadata columns consistent.","Build an issue catalogue and manifest; test how mixed, supplemental and missing files are represented.","Run the Step 2 checks and add journal-specific checks only where the source requires them.","Write source quirks and decisions in the journal onboarding notes so another student can reproduce them."])
    s += section("10","Handoff into Phase 3",[
        "Phase 3 begins only after Step 2 has a bounded set, traceable metadata and explicit file decisions. Its first task is to extract and inspect text, not to create embeddings. Extraction quality is a separate question from whether a PDF opens or has selectable text."])
    s += [title("10.1 Phase 3 inputs",2)] + bullets(["The 19 physical PDFs with unchanged source files.","The article catalogue with two Correspondence entries scoped out.","The file manifest with duplicate, News in Brief and Clippings treatment.","The issue contents page and source URLs.","Open metadata gaps: most authors and DOI values remain unverified in the catalogue and should be enriched before author-faceted search or final citations.","The access/use scope note: internal POC as stated by the user; external reuse confirmation remains separately recorded."])
    s += [title("10.2 Phase 3 should produce",2)] + bullets(["One extracted text artifact per selected source/article, with page and article ID provenance.","A processing log showing method/version and errors.","A sample inspection report for title, authors, headings, tables, footers, pages and reading order.","Cleaned text in a derived folder while raw PDFs stay unchanged.","A quality gate that blocks chunking for corrupt, incomplete or mismatched article text."])
    s += [title("References and glossary",1),P("The issue categories and article listing should be checked against the publisher's issue page when the corpus is refreshed. The current source is the official January 2025 issue page at https://indianpediatrics.net/articles.php?issue=766.")]
    add_glossary(s,[["Article catalogue","Structured records about editorial items in the issue."],["File manifest","Inventory describing each physical local file and its relationship to an article."],["Provenance","Traceable information about where an item came from and how it was handled."],["Content role","A controlled label explaining the intended evidence/search role of an item."],["Scoped out","Known issue entry deliberately excluded from this POC dataset by scope decision."],["Selectable text","Text that a PDF reader can extract; it does not guarantee correct reading order or completeness."],["Hybrid retrieval","A search approach combining semantic relevance with exact lexical and metadata matching."]])
    make_pdf("Step2.pdf","Step 2 | Define and Acquire the POC Corpus",s)

def build_step3():
    s=[]
    cover(s,"STEP 3","Data Processing","A beginner-to-practitioner guide to page-level PDF extraction, conservative cleaning, provenance, visual exceptions, and a repeatable data-quality gate.")
    s += [title("Document control and alignment"),P("This chapter follows <b>Phase 3 - Data Processing</b> in the project roadmap and the four numbered activities in the Implementation Guide: <b>14. PDF/HTML extraction, 15. Cleaning, 16. Metadata attachment, and 17. Quality inspection.</b> Only PDFs were supplied for the selected January 2025 Indian Pediatrics issue, so this implementation processes PDF files. There were no acquired HTML article files to process."),callout("Step 3 outcome", "17 acquired article PDFs were extracted page by page, producing 77 page records. Two Step 2 administrative/mixed files were excluded by policy. Source hashes confirm the 17 source PDFs were not changed. Quality review found one visual limitation: the systematic review's printed page 59 is a PRISMA flow-chart image and its counts are not searchable extracted text."),title("Contents at a glance")]
    s += bullets(["1. Purpose, inputs, outputs, and boundary","2. Activity 14 - extract PDF/HTML text","3. Page provenance and article structure","4. Activity 15 - clean conservatively","5. Activity 16 - attach metadata","6. Activity 17 - inspect quality","7. Processing architecture and code walkthrough","8. Recorded results and known exception","9. Reproduction, troubleshooting, and handoff"])
    s += section("1","Purpose, inputs, outputs, and boundary",[
        "Step 3 converts acquired documents into traceable text artefacts suitable for later chunking and retrieval. It must retain enough provenance to answer: which journal article did this text come from, which local source file, which physical PDF page, and which printed page if that mapping is known?",
        "Extraction does not mean interpretation. Cleaning removes a small class of mechanical artefacts while preserving the author's words, citations, headings, and page order. It must not summarize, correct medical claims, infer missing metadata, or silently reconstruct tables and figures."])
    s += [title("1.1 Inputs",2)] + bullets(["Step 2 `article_metadata.csv` and `corpus_file_manifest.csv`.","The 19 source PDFs under `data/raw/2025_Jan/`.","Explicit include/exclude decisions from Step 2.","A pinned PDF parser dependency and a stable local project environment."])
    s += [title("1.2 Outputs",2),*table(["Output","Purpose"],[
        ["data/processed/extracted/<article_id>.jsonl","One JSON record per PDF page, retaining raw and cleaned text, article metadata, physical and printed page references, role, image count and source hash."],
        ["data/processed/cleaned/<article_id>.txt","Readable article text with visible page boundary markers for inspection and future chunking."],
        ["data/processed/quality/processing_manifest.csv","One row per Step 2 file with processing status, source checksum, parser version, page totals and output paths."],
        ["data/processed/quality/page_quality.csv","One row per processed page with character counts, image count, page role and review status."],
        ["data/processed/quality/visual_review_log.csv","Human-readable decision for a page that has meaningful graphic content but little selectable text."],
        ["data/processed/step3_quality_report.md","Summary of checks, results, limitations and commands to reproduce the run."]],[62*mm,108*mm])]
    s += [title("1.3 Out of scope",2)] + bullets(["OCR or manual transcription of figure/table contents.","Chunking, embeddings, vector database, retrieval or LLM calls.","Clinical interpretation or correction of article content.","Fetching HTML or website content when no HTML corpus has been acquired.","Permission/licence determination."])
    s += section("2","Activity 14 - extract PDF/HTML text",[
        "PDFs store text and layout differently. Some contain searchable characters, some are images, and many mix normal text with tables and figures. Extraction is therefore a transformation with a measurable quality risk, not a guaranteed conversion."])
    s += [title("2.1 Why process page by page?",2),P("If an entire PDF becomes one text string, a missing or scrambled page is hard to locate. Page-level records allow every result to be traced to a source page, let a reviewer compare a page with its rendered appearance, and give later chunking a stable citation anchor."),title("2.2 What the current processor does",2)] + bullets(["Opens each PDF read-only with pypdf 6.10.0.","Enumerates physical pages starting at 1.","Extracts selectable text separately for each page.","Records physical page number, article ID, source filename, SHA-256 checksum and parser version.","Maps physical pages to printed article pages when page-range metadata makes that mapping direct.","Labels extra pages of the 56.pdf systematic review as unpaginated/supplement pages rather than dropping them.","Writes both original extracted text and conservatively cleaned text into page-level JSONL.","Writes a page-marked plain-text review copy for people and future chunking."])
    s += [title("2.3 Physical page and printed page are different",2),P("A physical page is the position in the supplied PDF. A printed page is the page number visible in the journal. Citations and provenance need the printed page where known; debugging extraction needs the physical PDF page. They must remain separate. For example, 56.pdf has 13 physical pages, while the article's printed pages run 56-62 and later PDF pages are supplemental material without journal pagination.")]
    s += [title("2.4 HTML case",2),P("The roadmap allows PDF or HTML sources. This corpus contains PDFs only, so the run uses no web crawler and does not fetch article pages. For a later HTML corpus, add a source adapter that preserves title, article sections, headings, tables, canonical URL and source timestamps; keep the same article/page-or-section provenance contract. Do not run a scraper just because the framework mentions HTML.")]
    s += section("3","Page provenance and article structure",[
        "A reliable text passage must retain its parent article identity. Later chunk IDs should link back to an article record and, where possible, a page and section. Step 3 lays that foundation before chunking exists."])
    s += [title("3.1 Page record fields",2),*table(["Field","Reason"],[
        ["article_id, title, journal, section, content_role","Connect page text with article catalogue and evidence-role policy."],
        ["issue_id, year, volume, issue_number","Support issue/time filtering and citations."],
        ["source_filename, source_relative_path, source_sha256","Identify the exact unchanged source and detect accidental replacement."],
        ["physical_page, printed_page, page_role","Keep PDF location distinct from journal citation page and supplementary material."],
        ["raw_text, cleaned_text","Allow audit of each normalization and future reprocessing."],
        ["embedded_image_count, character_count, quality_status","Make visual extraction gaps visible instead of treating sparse text as complete."],
        ["extractor name/version in processing manifest","Make processing reproducible and comparable after parser upgrades."]],[64*mm,106*mm])]
    s += [title("3.2 Structure preservation policy",2),P("This implementation preserves page boundaries and extracted line breaks. It does not attempt to detect every heading, paragraph, table cell or figure caption as a separate data object. Pypdf's text output can follow a PDF's internal reading order, which may differ from visual reading order in a two-column page. Keep the page JSONL as the audit layer. More advanced layout-aware extraction can be evaluated later on difficult pages rather than applied blindly to all pages.")]
    s += section("4","Activity 15 - clean conservatively",[
        "Cleaning should improve text usability without changing meaning. Every clean operation should be deterministic and inspectable. When in doubt, preserve the source text and report the issue instead of guessing."])
    s += [title("4.1 Normalizations used",2)] + bullets(["Unicode NFC normalization to combine canonically equivalent character sequences.","Normalize Windows, carriage-return and line-feed variants to newline characters.","Remove soft hyphen and zero-width formatting artifacts that may be inserted by text layout.","Expand common presentation ligature code points such as fi/fl into ordinary letter sequences.","Convert nonbreaking spaces and tabs to regular spaces; collapse repeated horizontal spaces.","Trim line edges and collapse runs of three or more newlines while retaining paragraph breaks and page separation.","Retain punctuation, minus signs, decimal values, units, citations, references and original line order."])
    s += [title("4.2 Deliberately not done",2)] + bullets(["No automatic spelling correction, paraphrasing, summarization or medical terminology rewriting.","No automatic joining of hyphenated line endings: some hyphens are genuine words, and a false merge is hard to detect.","No removal of headers, footers, references or repeated content at this stage; later filtering needs its own checks.","No conversion of tables or figures into guessed prose.","No replacement of an unknown glyph with a guessed character."])
    s += [callout("Raw plus clean is an audit pair", "The JSONL keeps the parser output and normalized text side by side. If a later model answer looks wrong, the team can determine whether the defect came from the source PDF, extraction, normalization, chunking, retrieval or generation.")]
    s += section("5","Activity 16 - attach metadata",[
        "Metadata is attached at the page record level from the Step 2 article catalogue and file manifest. This avoids asking the language model to guess authors, date, issue, category or source link from prose. The processing manifest remains separate from the article catalogue so each stage can report its own status."])
    s += [title("5.1 Metadata attachment rules",2)] + bullets(["Use the stable article_id as the join key between the catalogue, manifest, page text and future chunks.","Carry article title, section and content_role into each page record so downstream filters can act locally.","Copy publication fields from validated catalogue records; do not infer missing author or DOI values.","Keep an empty printed page value when it cannot be mapped confidently.","Keep supplements explicitly labelled and linked to the article while retaining their physical page number.","Verify the first extracted page against the catalogue title; a mismatch is a data-integrity warning."])
    s += [title("5.2 Why no author matching by PDF text?",2),P("PDF title pages often contain author names and affiliations, but extracting and normalizing them is a separate metadata validation task. Automated parsing can merge affiliations into names or split compound names. The present pipeline attaches verified Step 2 values and leaves unknown fields blank. Author-search completeness is a later enrichment task, not a reason to invent data.")]
    s += section("6","Activity 17 - inspect quality",[
        "A correct program exit is not enough. The quality check compares file identity, page counts, article IDs, page order, text presence, normalization output, and a text-to-catalogue title match. It also creates explicit exceptions when a page has little selectable text."])
    s += [title("6.1 Automated quality checks",2),*table(["Check","Defect it can detect"],[
        ["Manifest coverage","A Step 2 file was omitted or an unlisted file entered processing."],
        ["Source SHA-256 equality","A raw source changed after processing or outputs point at a replacement file."],
        ["PDF page count vs page-record count","A page was skipped, duplicated or miscounted."],
        ["Continuous physical page sequence","A provenance gap in page records."],
        ["Article ID and source-hash consistency","Text is joined to the wrong article or source."],
        ["Nonblank page text","A missing text layer or unusable page."],
        ["Title token overlap","Possible mismatch between issue metadata and local PDF."],
        ["Replacement-character scan","Unicode decode failures that could corrupt names or medical terms."],
        ["Supplement role coverage","Extra pages were not silently discarded."],
        ["Visual review log","Sparse/graphic pages have an explicit, reviewable disposition."]],[58*mm,112*mm])]
    s += [title("6.2 Human visual review",2),P("Automated counts cannot tell whether a figure is meaningful or a table was reordered. Render flagged and representative pages and compare them with extracted text. The review should record the PDF file, physical page, printed page, what was observed, what the text layer missed, and the decision. Do not write a human transcription as if it were publisher text; label its source and require verification.")]
    s += [title("6.3 Thresholds are review triggers, not truth",2),P("The current 200-character threshold flags a page for review; it does not automatically mean extraction failed. A page can be a diagram, a full-page table, or mostly white space. Conversely, a page with thousands of characters can still have columns in the wrong order. Thresholds guide inspection; visual comparison and provenance checks provide context.")]
    s += section("7","Processing architecture and code walkthrough",[
        "The workflow is intentionally two commands: the processor creates deterministic outputs; the checker audits them and writes a report. Separating the two makes it possible to rerun validation without recomputing all text, and to inspect changes after parser updates."])
    s += [P("<b>Processor:</b> `scripts/process_step3.py`<br/><b>Checker/report:</b> `scripts/check_step3.py`<br/><b>Library:</b> pypdf 6.10.0, pinned in `requirements.txt` and `pyproject.toml`", "Calloutx"),title("7.1 Processing sequence",2)] + bullets(["Read both Step 2 CSVs and map article_id to catalogue metadata.","Iterate the source manifest in stable order; hash the raw file before reading.","Skip only explicit administrative duplicate/news roles or files without article identity.","Open each PDF without modifying it; reject encrypted/unreadable inputs visibly.","Extract each page; normalize text; calculate page role, character counts and image counts.","Write JSONL pages and page-marked text using article IDs as filenames.","Write one processing-manifest row for every input file, including excluded files.","Run checker, reconcile failures and review flags, and retain the report."])
    s += [title("7.2 Commands",2),P("From a PowerShell window opened in the Project root:"),P(".\\.venv\\Scripts\\Activate.ps1<br/>python scripts\\process_step3.py<br/>python scripts\\check_step3.py", "Calloutx"),P("Use the same pinned dependency version when regenerating the corpus. If the extractor version changes, retain the old manifest/report or commit a new versioned run so differences can be audited.")]
    s += section("8","Recorded results and known exception",[
        "The current checked run reports <b>12 PASS, 0 FAIL, 1 documented visual limitation</b>. It is ready to hand off to Phase 4 only with that limitation carried forward."])
    s += [title("8.1 Quantitative summary",2),*table(["Measure","Result"],[
        ["Manifest entries","19 physical PDFs listed"],["Article PDFs processed","17"],["Administrative/mixed PDFs excluded","2 (duplicate commentary ending/access notice; News in Brief)"],["Pages represented","77"],["Page text records","77 ordered page-level JSONL records"],["Unpaginated/supplement pages retained","6 pages from 56.pdf"],["Blank extracted pages","0"],["Unicode replacement characters","0"],["Title-to-first-page token overlap","17 of 17 exceeded the 80% check threshold"],["Raw source checksum changes","0"]],[72*mm,98*mm])]
    s += [title("8.2 Documented visual limitation",2),P("The systematic review PDF (`56.pdf`), physical page 4 / printed page 59, contains Figure 1, a PRISMA flow chart. Pypdf extracts only the page header and figure caption (90 cleaned characters); one embedded image is detected. Visual review confirms the page is not blank and contains screening-flow counts. Those counts are not part of searchable text and must not be cited as if they were retrieved. The original page remains preserved and the limitation is listed in `visual_review_log.csv` and the quality report."),callout("Phase 4 guardrail", "The article's surrounding searchable prose may be used subject to the normal evidence checks. Do not answer a question that depends on the diagram's exact counts from this text index until a separately labelled OCR or manual transcription has been checked against the source figure.")]
    s += [title("8.3 Quality interpretation",2),P("All files were structurally readable, all 77 physical pages have ordered records, the source hashes remain unchanged, and the article titles agree with the first-page text. That is a strong extraction baseline. It is not proof that every table cell, diagram label, formula, or two-column reading order is accurate. Review the source page when the answer depends on fine-grained layout content.")]
    s += section("9","Reproduction, troubleshooting, and handoff",[
        "A fresh developer should be able to regenerate the derived files from the source PDFs and compare the resulting quality report. Raw inputs remain read-only; delete or replace only derived outputs when intentionally rerunning the processor."])
    s += table(["Symptom","Likely cause","Action"],[
        ["Import error for pypdf","Dependency not installed in the active virtual environment.","Activate `.venv`; install from the project requirements file."],
        ["PDF count differs from manifest","A file was added/removed after Step 2 inventory.","Return to corpus inventory, update manifest deliberately, then rerun."],
        ["Encrypted or malformed PDF","Input cannot be read by parser.","Do not silently skip; record failure and obtain a usable authorized copy."],
        ["A page has very few characters","Graphic/table page, scan, or extraction defect.","Render page, inspect it, log disposition; OCR or transcribe only with verification."],
        ["Page/heading order looks wrong","PDF text order differs from visual columns.","Retain raw PDF and evaluate layout-aware extraction on that page; compare outputs before adopting."],
        ["Clean text differs unexpectedly","Normalization may have changed an artifact.","Compare raw_text and cleaned_text in JSONL and adjust only deterministic cleaning rules."]],[48*mm,57*mm,65*mm])
    s += [title("9.1 Phase 4 handoff checklist",2)] + bullets(["Run the Step 3 checker and retain its exact output/report.","Ensure all required article outputs exist and source hashes match.","Carry the PRISMA figure exception into the index policy and answer safeguards.","Decide which content roles are eligible for each query type; nonclinical education content should not support clinical advice.","Confirm supplement page treatment for 56.pdf before chunking its appendices.","Only then proceed to chunking while retaining article ID, section and page provenance on every chunk."])
    s += [title("References and glossary",1)] + bullets(["Ver 1 - Complete Implementation Guide for POC.pdf, Phase 3 Data Processing.","Ver 1 - Master Guide for POC.pdf, sections on extraction, data quality and chunk provenance.","Project scripts/process_step3.py, scripts/check_step3.py, data/processed/step3_quality_report.md, page_quality.csv and visual_review_log.csv."])
    add_glossary(s,[["Physical page","One-based position in the PDF file."],["Printed page","Journal page number shown on the document, if confidently mapped."],["JSONL","A text file containing one JSON object per line; here, one page record per line."],["SHA-256","A cryptographic checksum used to identify whether source bytes changed."],["OCR","Optical character recognition: machine reading of text from page images."],["Page provenance","Metadata linking extracted text to source file, article and page."],["Visual limitation","Meaningful page content is present in the PDF but is not available as searchable extracted text."]])
    make_pdf("Step3.pdf","Step 3 | Data Processing",s)

def build_step4():
    s=[]
    cover(s,"STEP 4 | RETRIEVAL-AUGMENTED GENERATION","From cleaned pages to cited literature answers","This chapter explains how the POC turns traceable page text into searchable evidence, retrieves relevant passages, and constrains any generated answer to those passages.")
    s += [title("Chapter map",1)] + bullets(["18. Chunking - create manageable, page-linked passages.","19. Embeddings - represent meaning, with external processing gated.","20. Vector database - store searchable text and optional vectors.","21. Retrieval - apply metadata filters and evidence limits.","22. Hybrid search - combine lexical and semantic rankings.","23. RAG generation - draft only from retrieved passages.","24. Citations - display source metadata and validate labels.","25. No-answer logic - abstain when evidence or safe support is absent."])
    s += [title("Learning objectives",1)] + bullets(["Explain how each chunk retains article, issue, source file, checksum, and page provenance.","Rebuild the local lexical index without sending corpus text to a provider.","Describe the difference between lexical matching and semantic vector similarity.","Trace how retrieved evidence is labelled and exposed as a source citation.","Recognize the current checkpoint boundary: local search is available; provider-backed semantic search and answer generation are not enabled."])
    s += section("18","Chunking",["A chunk is a bounded passage used as the unit for retrieval and evidence. This POC chunks each cleaned source page independently, targeting 1,400 characters with an overlap of 180 characters. Keeping page boundaries makes provenance and citation review simple; long pages become multiple overlapping chunks."])
    s += [title("18.1 What, why, and how",2)] + bullets(["What: split the Step 3 page records into small text passages, attach article metadata to each, and record any excluded flagged page.","Why: an entire issue or article is too broad for focused retrieval, while a sentence-only fragment can lose context. A page-linked passage is a transparent starting compromise.","How: `scripts/prepare_step4_chunks.py` reads `processing_manifest.csv`, article metadata, and ordered Step 3 JSONL page records. It writes `chunks.jsonl` and `chunk_exclusions.jsonl` under `data/processed/chunks/`."])
    s += [title("18.2 Stable identifiers and provenance",2)] + bullets(["Each chunk ID is based on article ID, printed page (or PDF page fallback), and sequence on that page.","Every chunk keeps article title, authors, section/category, content role, year, month, volume, issue, issue ID, printed page, physical page, source filename, source SHA-256, publisher URL, and page role.","The systematic review flow diagram page previously flagged for visual review is excluded from chunks. The exclusion is logged, not erased; its source PDF and Step 3 review record remain available.","The text passage itself is derived data. The original PDF remains the source of truth."])
    s += [title("18.3 Chunking quality and trade-offs",2),*table(["Choice","Benefit","Limit"],[
        ["Page-scoped chunks","Page provenance remains exact and easy to cite.","A concept spanning a page break may be split."],
        ["1,400 character target","Keeps evidence focused while leaving paragraph context.","Not calibrated yet on a golden retrieval set."],
        ["180 character overlap","Preserves some context across splits within a page.","Can create near-duplicate results."],
        ["Long lines split on word boundaries","Avoids very large chunks and broken words.","Complex tables and columns need visual checking."]],[42*mm,64*mm,64*mm])]
    s += [title("18.4 Common mistakes to avoid",2)] + bullets(["Do not remove page and source metadata after cleaning.","Do not chunk flagged figure pages as if all labels were extracted.","Do not choose chunk length based only on a popular tutorial; evaluate it against the journal's article layouts and Step 6 questions.","Do not call character overlap a guarantee that a complete scientific argument is preserved."])
    s += section("19","Embeddings",["An embedding is a numeric representation that can make passages with related meaning discoverable even when they use different words. The POC defines `text-embedding-3-small` as its intended embedding model, but it does not fabricate embeddings or use a lexical score as a semantic substitute."])
    s += [title("19.1 What, why, and how",2)] + bullets(["What: send a query and candidate text passages to a configured embedding model and receive vectors of equal dimensions.","Why: lexical search is good for exact names, phrases, and terms; semantic retrieval can help with paraphrases and related concepts.","How: the optional `--with-embeddings` index build calls the provider in configured batches. It requires a local API key and the explicit `JOURNAL_ASSISTANT_ALLOW_EXTERNAL_TEXT_PROCESSING=true` gate."])
    s += [callout("Privacy and corpus permission gate","The default is disabled. An embedding request transmits article passages to an external service. A key alone does not grant permission. The project owner must review publisher/editor terms and approve this data flow before enabling it. The current run made no such API request."),title("19.2 Reproducibility and model identity",2)] + bullets(["Record the embedding provider, exact model, dimensions, index build time, and input checksum in a production manifest.","Do not mix vectors from different models or dimensions in one index.","If the model changes, re-embed the complete approved corpus and compare retrieval using a fixed evaluation set.","Keep query embedding behavior consistent with document embedding behavior."])
    s += section("20","Vector database",["The POC starts with SQLite: FTS5 stores searchable text, and an optional table stores float vectors and model dimensions. This is deliberately a small, local and inspectable index for one issue, rather than a commitment to a production-scale vector service."])
    s += [title("20.1 What, why, and how",2)] + bullets(["What: persist one row per chunk and a parallel FTS record; optionally store the vector as a binary float array.","Why: the first corpus is small enough for simple deployment and straightforward inspection. One SQLite file is easier to back up and demonstrate than a separately operated service.","How: `SQLiteHybridStore` creates `data/indexes/journal_assistant.sqlite3`, enforces one row per chunk ID, and exposes lexical and cosine-similarity searches."])
    s += [title("20.2 Why SQLite now; what may change later",2),*table(["Option","POC use","Later consideration"],[
        ["SQLite FTS5 + vector table","No separate server; local, portable, transparent.","Benchmark latency and vector count before scaling."],
        ["Dedicated vector database","Not needed for this one-issue POC.","Consider only if multi-tenant, large-scale corpus, access control or operations justify it."],
        ["In-memory mock vectors","Rejected because they would imply semantic capability without real embeddings.","Use deterministic fixtures only in isolated unit-level tests, never as production evidence."]],[46*mm,61*mm,63*mm])]
    s += [title("20.3 Index integrity",2)] + bullets(["Rebuild is explicit and resets the derived index before loading the selected chunk file.","A local lexical build stores zero vectors; the checkpoint calls this out rather than hiding it.","Index rows keep full metadata and the chunk text so that search results can be audited and citations constructed without guesswork.","Back up the raw corpus and generated manifests separately from the disposable derived SQLite index."])
    s += section("21","Retrieval",["Retrieval selects passages to support a question before answer generation. It applies query text, allowed content roles, and optional metadata constraints such as author, year, volume, issue and article ID."])
    s += [title("21.1 What, why, and how",2)] + bullets(["What: search chunk records, apply filters, rank matches and retain a small evidence set.","Why: restricting evidence to the right article, time range, or content type helps relevance and reduces unrelated context.","How: `retrieval.search` accepts a lexical query and optionally an already-computed vector, applies allowed roles/filters through the store, then returns up to the configured top six passages."])
    s += [title("21.2 Recency and ranking",2),P("The metadata supports time filtering and future recency-aware ordering. This POC does not make newer research automatically more correct: evidence rank and publication date are distinct concepts. The current retrieval can constrain year ranges and exact issue/year/volume; a validated temporal boost should be added only after evaluation. The published year, month and issue remain visible in source cards.")]
    s += [title("21.3 Content roles",2)] + bullets(["Clinical evidence and clinical context are eligible for the default literature query; secondary sources receive a ranking penalty.","Administrative material and advertisements are not included in the default evidence roles.","Role filtering is not a substitute for judging study design, population, sample size, limitations, or subsequent research.","The UI should distinguish a journal literature summary from clinical guidance."])
    s += section("22","Hybrid search",["Hybrid search can combine lexical and semantic ranking. The POC uses reciprocal rank fusion (RRF), which combines positions rather than mixing raw scores with incomparable scales."])
    s += [title("22.1 What, why, and how",2)] + bullets(["What: obtain lexical results from FTS5 and, when real query and document vectors exist, obtain semantic results from cosine similarity.","Why: exact medical terms and author names benefit from lexical search; paraphrased topics may benefit from embeddings.","How: RRF adds a reciprocal rank contribution from each ranked list, caps duplicate chunks per article, and applies a configurable lower multiplier to secondary-source results."])
    s += [title("22.2 Current behavior",2),P("The current POC index contains only its local lexical list. Calling hybrid retrieval without a query vector therefore returns lexical matches only. This is an honest fallback, not semantic retrieval. After explicitly approved embedding generation, supply a query embedding to the same retrieval interface to combine both lists.")]
    s += [title("22.3 What to evaluate",2)] + bullets(["Recall at k: did relevant articles appear in the first k results?","Precision at k: how many returned passages are actually relevant?","Author/issue filter correctness: are out-of-filter rows excluded?","Source diversity: does one long article crowd out all others?","Compare lexical-only, semantic-only and hybrid on a reviewed question set before tuning weights or top-k."])
    s += section("23","RAG generation",["Retrieval-augmented generation (RAG) supplies selected source passages to a language model for a grounded response. The provider adapter describes this boundary, but the present environment has no configured key and external text processing remains off."])
    s += [title("23.1 What, why, and how",2)] + bullets(["What: combine a user question and retrieved evidence into a constrained request to the answer model.","Why: the model is asked to synthesize evidence actually selected from this journal corpus rather than answer freely from its general training.","How: the adapter labels each passage and instructs the model to stay within the evidence, describe publications as evidence rather than recommendations, and disclose insufficient or conflicting evidence."])
    s += [title("23.2 Safety boundary",2)] + bullets(["The assistant is a literature-retrieval aid, not a clinical decision-maker.","The initial patient-specific phrase detector is a narrow prototype boundary, not a complete medical safety classifier.","Never rely on a prompt alone: keep source evidence visible, validate citations, and evaluate adversarial and ambiguous questions.","Do not describe the POC as clinically validated or suitable for diagnosis or treatment."])
    s += section("24","Citations and source cards",["Citations are built from the retrieved chunk's stored metadata rather than free-form model claims. Results receive labels such as [S1] and carry the article, authors, year, category, page, and publisher issue URL."])
    s += [title("24.1 What, why, and how",2)] + bullets(["What: assign labels after ranking and include the same labels beside passages supplied for synthesis.","Why: the reader needs to verify a statement against the source PDF; source pages and article identity let them retrace it.","How: the answer validator accepts only citation labels present in the retrieved evidence list and rejects missing or invented labels."])
    s += [title("24.2 Citation validation limits",2),P("A label check verifies that the model used a source ID that exists. It does not prove that the cited passage logically supports the sentence. Human review and claim-level evaluation remain necessary. A final desktop interface should let users open the source document at the cited page and should identify when only a physical PDF page is known.")]
    s += section("25","No-answer logic and safe fallback",["A reliable assistant sometimes declines to answer. No relevant search results, missing provider setup, or invalid citation output must not be disguised as a confident response."])
    s += [title("25.1 What, why, and how",2)] + bullets(["No evidence: return an explicit message that the indexed journal corpus did not yield support.","Provider unavailable: return the retrieved source passages and say generation is not configured.","Patient-specific request detected: return the fixed literature-assistant boundary message.","Invalid or absent citations: refuse the generated text and ask the user to inspect the actual retrieved sources.","Conflicting or limited literature: the generation instructions ask the model to state that limitation rather than force a single conclusion."])
    s += [title("25.2 Calibrating abstention",2),P("`minimum_evidence_count` currently expresses a starting configuration, not a clinically validated threshold. Step 6 must establish relevance and abstention thresholds on a reviewed question set. Do not interpret a lexical match as proof that a question is answered, or a zero-result response as proof that the journal contains no such information.")]
    s += [title("Reusable multi-journal configuration",1),P("The implementation separates corpus-specific data from shared retrieval logic. A new journal must receive its own explicit configuration, metadata mapping and permission review; it must never silently inherit Indian Pediatrics assumptions.")]
    s += [title("Portability checklist",2)] + bullets(["Create a journal profile for display name, canonical source URL, section taxonomy, identifier rules, volume/issue conventions, and allowed content roles.","Map the new journal's metadata into the common schema while preserving original field names and values for audit.","Use journal-prefixed article IDs and retain source checksums and access terms.","Review file acquisition and external provider permission independently for the new publisher.","Test extraction, chunking, filters, citations, role behavior and safety using that journal's own sample issue.","Keep shared code generic; place per-journal behavior in named config and adapters rather than hard-coded conditionals."])
    s += [title("Local reproduction and troubleshooting",1),P("All corpus processing and local lexical retrieval can be demonstrated without an AI API key. These commands operate from the Project folder.")]
    s += [P("Activate the virtual environment, then run the commands in order:") ,P("python scripts\\prepare_step4_chunks.py<br/>python scripts\\build_step4_index.py<br/>python scripts\\check_step4.py<br/>python scripts\\ask_step4.py \"ketorolac morphine sickle cell\"", "Calloutx")]
    s += table(["Symptom","Likely cause","Action"],[
        ["No chunks found","Step 3 derived records or metadata are missing.","Run Step 3 checkpoint; do not invent text to fill gaps."],
        ["Issue page is not in the result","Page may have a visual-review flag or wording differs.","Check exclusion ledger and original PDF; refine query or review the page."],
        ["Semantic results absent","No approved embeddings have been built.","Use local lexical retrieval or enable external processing only after policy review and configuration."],
        ["Answer generation unavailable","Missing key, missing SDK or external-processing gate remains off.","Keep source results available; configure provider only after approval."],
        ["Generated citation rejected","Output label does not match retrieved evidence.","Do not display as supported; inspect prompt and provider output, then re-evaluate."],
        ["A retrieved passage is irrelevant","Lexical overlap does not ensure relevance.","Record the query in the evaluation set; tune and measure rather than silently raising confidence."]],[46*mm,58*mm,66*mm])
    s += [title("Checkpoint results and handoff",1),P("The checker writes a repeatable report and distinguishes local retrieval checks from provider readiness. The current checkpoint must be read alongside the Step 3 documented figure-page exception.")]
    s += [title("Completion checklist",2)] + bullets(["Chunk files exist and have stable IDs, nonempty text and source provenance.","Flagged figure pages are excluded and listed in the exclusion log.","Local FTS index row count matches chunk count; a known corpus query returns source-linked results.","A nonsense query yields no evidence; no-answer behavior is exercised without an API call.","Author/year/issue metadata filters and allowed content roles are checked.","No vectors or generated answers are claimed unless a real approved provider call created them.","The report states provider/key/approval status without exposing credentials."])
    s += [title("Current status and Step 5 handoff",2),callout("Implementation foundation complete; full Step 4 is gated","Local page-aware chunking and lexical search can be checked. The provider-backed semantic index and answer-generation path have not been activated. The check report must show this as a hold before Step 5's quality/evaluation phase can treat the RAG path as complete.",colors.HexColor("#FFF3D8")),P("This chapter describes implemented interfaces and a limited current POC run. It does not establish that answers are clinically safe, that all retrieved text is relevant, or that the publisher permits external AI processing. Preserve the source PDFs, processing reports, chunk exclusions and index build provenance for the next phase.")]
    s += [title("References and glossary",1)] + bullets(["Ver 1 - Complete Implementation Guide for POC.pdf, Phase 4 Retrieval-Augmented Generation and its activities 18-25.","Ver 1 - Master Guide for POC.pdf, source traceability, grounded literature assistance, safety and reusable-journal principles.","Project configuration: `config/rag.toml`; implementation: `src/journal_assistant/rag/`; local commands: `scripts/prepare_step4_chunks.py`, `scripts/build_step4_index.py`, `scripts/ask_step4.py`, and `scripts/check_step4.py`."])
    add_glossary(s,[["Chunk","A bounded passage indexed for retrieval."],["Embedding","A numeric vector intended to represent text meaning."],["FTS5","SQLite's full-text search extension used for local lexical search."],["Hybrid retrieval","Combining ranked results from lexical and semantic search."],["RRF","Reciprocal rank fusion, a method for combining ranked lists."],["Provenance","Information linking derived text to article, file, checksum and page."],["Abstention","A deliberate no-answer when available evidence is insufficient or invalid."],["Grounded answer","A response constrained to retrieved passages with traceable citations."]])
    make_pdf("Step4.pdf","Step 4 | Retrieval-Augmented Generation",s)

def build_step5():
    s=[]
    cover(s,"STEP 5 | APPLICATION","A local interface for search, evidence and comparison","This chapter explains how the first user-facing application presents hybrid journal search results, source provenance, article comparison and metadata filters, with optional answer synthesis behind the explicit processing-consent gate.")
    s += [title("Chapter map",1)] + bullets(["26. Streamlit UI - create a simple Windows-friendly local interface.","27. Search - connect the question and metadata filters to the local index.","28. Answer - present gated, structured, citation-checked synthesis or an explicit fallback.","29. Sources - expose article, page, source file and publisher traceability.","30. Compare - place retrieved passages from selected articles side by side.","31. Filter by article type - constrain retrieval to selected journal sections."])
    s += [title("Learning objectives",1)] + bullets(["Run the application locally from the Project folder.","Explain which logic belongs in the interface and which belongs in shared retrieval modules.","Distinguish a retrieved passage from an answer synthesized by a language model.","Trace an evidence card back to issue metadata and a local source PDF.","Configure the same interface for a future journal without hard-coding its name or corpus directory."])
    s += section("26","Streamlit UI",["Step 5 places a small local interface over the Step 4 retrieval layer. It is a demonstration front end, not the final packaged Windows desktop product. Streamlit runs a local application server and opens its interface in a browser window; its documented launch command is `streamlit run your_script.py`."])
    s += [title("26.1 What, why, and how",2)] + bullets(["What: a search page with question input, article-type/year/author filters, source cards, side-by-side comparison, and a visible safety boundary.","Why: editors and students can see the evidence trail and workflow before investing in a fully native or packaged desktop interface.","How: `app/streamlit_app.py` loads the journal profile and calls shared configuration, retrieval and answer-boundary code. `scripts/run_ui.py` launches the local Streamlit server using the active project Python environment."])
    s += [title("26.2 Why this interface first",2),*table(["Option","Why it fits this POC","What to revisit later"],[
        ["Streamlit local UI","Fast to build, easy to inspect, and Python-native for this one-issue demonstration.","Packaging, multi-window behavior, polished Windows installation and offline updates."],
        ["Native Windows UI","Could feel like a conventional installed desktop program.","Would add UI and packaging work before the retrieval workflow is evaluated."],
        ["Web front end with API backend","Good separation for a deployed service or multi-user product.","Adds a separate service and deployment boundary not needed for the local demo."]],[43*mm,67*mm,60*mm])]
    s += [title("26.3 Page structure and state",2)] + bullets(["The journal name, corpus title, metadata file and source-PDF folder come from the selected journal profile.","The sidebar holds article type, year, author and result-count controls; the main panel holds the question, answer status, sources and comparison.","A search action stores its retrieved evidence and status in session state so that Streamlit reruns do not discard the current result.","The optional Groq provider is called only when the local external-processing consent gate is enabled, credentials are present, evidence was retrieved, and the question is not patient-specific."])
    s += section("27","Search",["Search turns a question and optional metadata constraints into candidates from the local index. The current configured index combines local lexical full-text and FastEmbed semantic retrieval, then uses reciprocal-rank fusion to order results."])
    s += [title("27.1 What, why, and how",2)] + bullets(["What: pass the question, selected section types, publication year, author text, allowed content roles, query embedding and desired result count to the shared retrieval module.","Why: a focused query and filters help the reader find specific published material and limit unrelated issue content.","How: the UI loads `config/rag.toml`, embeds the query locally, calls `retrieval.search` for hybrid ranking, and renders the ranked passages. Groq is used separately for optional answer synthesis."])
    s += [title("27.2 Search behavior and limits",2)] + bullets(["Lexical and vector results are combined; neither a high semantic match nor a lexical match by itself proves that a passage answers the question.","Author and year filters constrain metadata. Article types are mapped to the stored journal section/category.","The current corpus is one issue from 2025, so a later-year filter will naturally return no records.","The model can abstain when retrieved context does not answer the question, but its abstention and grounding still require evaluation.","The semantic similarity cutoff is an initial POC setting, calibrated only against the current small Golden Test Set; it must be retuned on a broader corpus."])
    s += [title("27.3 Interface-to-backend boundary",2),P("The Streamlit file should collect input, call stable shared functions, and display results. It should not implement its own ranking formula, citation rules, PDF parser, or provider client. Keeping those decisions in `src/journal_assistant/rag/` makes a future desktop or web front end reuse the same behavior.")]
    s += section("28","Answer",["The answer area is status-aware. When configured, the gated Groq provider receives the question and retrieved passages, and returns structured claims with source IDs. The application verifies those IDs against retrieved evidence and adds visible citations from its own source records."])
    s += [title("28.1 What, why, and how",2)] + bullets(["What: show generated, no-evidence, patient-specific boundary, unavailable-provider, or generation-error states.","Why: users must distinguish source discovery from AI synthesis and see when the model abstains.","How: `answer_question` blocks patient-specific questions, returns a no-evidence state when no passages are found, parses the provider's structured output, and rejects empty or invalid source IDs. The UI renders source cards using the original retrieved records."])
    s += [callout("Current answer status","The configured Groq path has passed a basic structured-citation example and an out-of-corpus abstention example. This is a limited technical validation, not clinical validation or a substitute for human review.",colors.HexColor("#FFF3D8")),title("28.2 Safety presentation",2)] + bullets(["Keep the research-literature-only warning visible near the question input.","A narrow patient-specific phrase detector is only a prototype safeguard; it is not a complete safety classifier.","Do not turn a search result into treatment advice or imply that one paper establishes a universal clinical recommendation.","The application verifies that cited source IDs were retrieved. A human must still verify that each passage substantively supports its claim."])
    s += section("29","Sources",["Source cards make the evidence trail visible. Each card uses fields attached to its chunk, rather than asking a model to invent a bibliographic reference."])
    s += [title("29.1 What, why, and how",2)] + bullets(["What: display source label, article title, authors when verified, year, category, volume, issue, journal page, physical PDF page, source filename and abbreviated source checksum.","Why: a reader needs to inspect the actual article passage and see which page and file it came from.","How: source labels are assigned after retrieval. The UI links to the publisher issue page and offers a local source-PDF download when that file exists in the configured source directory."])
    s += [title("29.2 Citation traceability and limits",2)] + bullets(["A source label points to a retrieved chunk, not automatically to claim-level proof.","Printed journal page and physical PDF page are shown separately because they may differ.","The source checksum is a short display of the full SHA-256 retained in metadata; it helps distinguish the corpus file used.","The link currently opens the issue landing page. A later interface can add direct PDF page navigation after confirming stable publisher URLs and permission.","Keep original source PDFs unchanged; the download button serves the configured local copy."])
    s += section("30","Compare",["The comparison panel lets a reader inspect two or more retrieved articles beside one another. This is a passage comparison interface, not a generated synthesis of study findings."])
    s += [title("30.1 What, why, and how",2)] + bullets(["What: choose articles present in the current result set and view their article type, authors, year, article ID and matching passages in columns.","Why: researchers often need to compare related publications, methods or evidence types, and seeing each passage separately preserves its context.","How: the UI groups retrieved chunks by article ID and displays up to three selected articles side by side with their source labels."])
    s += [title("30.2 Avoiding false comparison",2)] + bullets(["Do not claim one study is superior based only on lexical matches or an excerpt.","Do not treat two passages as methodologically comparable until design, population, outcomes and limitations are reviewed in the full articles.","Do not hide disagreement or limitations. A future synthesis workflow must cite each claim to the relevant source and be tested against reviewed examples.","For the current POC, the reader performs the interpretation; the interface only organizes retrieved evidence."])
    s += section("31","Filter by article type",["Article type or section filters let users narrow retrieval to the journal's editorial categories, such as Original Article, Systematic Review, Medical Education, or Correspondence."])
    s += [title("31.1 What, why, and how",2)] + bullets(["What: a multi-select control populated from the current journal metadata catalogue.","Why: category can change how a paper should be interpreted and which material is useful for a research question.","How: selected values are passed as a set of exact section filters; the local store excludes rows whose section is not selected."])
    s += [title("31.2 Data requirements and limitations",2)] + bullets(["A category filter is only as accurate as the article metadata file; the UI cannot correct a misclassified record by itself.","Category labels may differ between journals. Keep original journal labels and use a per-journal taxonomy mapping if normalized labels are added later.","An empty multi-select means all eligible default roles; it does not remove role-based exclusions for administrative or advertisement records.","Use the article title and source card to confirm a selected result's category before citing it."])
    s += [title("Reusable setup for another journal",1),P("To adapt the UI, copy the journal template, set its display name and initial corpus details, and point the `[corpus]` fields to that journal's metadata CSV and raw source folder. The metadata must follow the shared schema or an explicit journal adapter must map it. The application reads `JOURNAL_ASSISTANT_CONFIG`; it does not infer or download a new publisher's corpus automatically."),callout("Permission is journal-specific","A local interface does not create permission to collect, index, or share another publisher's articles. Record and review access terms for each journal before using its source material.")]
    s += [title("Checkpoint and troubleshooting",1),P("`scripts/check_step5.py` runs an in-process Streamlit smoke test and exercises a known query, article-type filter, no-result question, and patient-specific boundary. It makes no provider calls and writes `data/processed/step5_checkpoint.md`.")]
    s += table(["Symptom","Likely cause","Action"],[
        ["Streamlit command not found","Virtual environment is inactive or dependency is missing.","Activate `.venv` and run the pinned requirements installation."],
        ["The index is not built","Step 4 local index is absent.","Complete the local Step 4 chunk/index commands; do not enable external processing just to run the UI."],
        ["No passages appear","Query terms or metadata filters do not match this one-issue index.","Remove optional filters, try article title terms, and inspect the Step 4 checkpoint."],
        ["No generated answer","Expected while provider-backed RAG remains unconfigured.","Review the displayed source passages; Step 4 provider setup and validation are still required."],
        ["Wrong article type appears","Metadata field is inaccurate or category values differ.","Correct the controlled metadata record and rerun its quality checkpoint."],
        ["Source PDF download is missing","Local raw file is absent or a source filename is wrong.","Check the journal profile source folder and file manifest; preserve the original issue file."]],[43*mm,58*mm,69*mm])
    s += [title("Step 5 checkpoint outcome",1),callout("Application checks passed","The Step 5 UI smoke check covers app rendering, local hybrid retrieval, article-type filtering, no-result handling, and the patient-specific boundary. Provider-backed generation is conditionally available when the local consent switch and credentials are present. The Step 6 evaluation records the limited live answer checks.",PALE),P("A green Step 5 UI check means the local application workflows render and basic interactions run. It does not imply clinical validation, complete journal coverage, or permission for external sharing.")]
    s += [title("References and glossary",1)] + bullets(["Ver 1 - Complete Implementation Guide for POC.pdf, Phase 5 Application and activities 26-31.","Ver 1 - Master Guide for POC.pdf, user interface and quality-assurance principles.","Streamlit official run instructions: `https://docs.streamlit.io/develop/concepts/architecture/run-your-app`.","Project files: `app/streamlit_app.py`, `scripts/run_ui.py`, `scripts/check_step5.py`, `config/journals/`, and `data/processed/step5_checkpoint.md`."])
    add_glossary(s,[["Session state","Values Streamlit retains across a user's interactions and reruns."],["Lexical search","Search based on words and terms present in indexed text."],["Source card","A UI item showing a retrieved passage and its verified provenance fields."],["Article type","The editorial section/category assigned in the journal metadata."],["Local application server","A program serving the UI on the same computer for the POC."],["Extractive display","Showing retrieved source text without claiming it is an AI-generated summary."]])
    make_pdf("Step5.pdf","Step 5 | Application",s)

def build_step6():
    s=[]
    cover(s,"STEP 6 | VALIDATION","Test whether retrieval, answers, citations and safety behavior meet stated targets","This chapter follows the roadmap's numbered validation activities 32-37. It creates a small Golden Test Set, measures article-level retrieval, tests structured source IDs and abstention, fixes a citation-format defect, and records what still requires expert review.")
    s += [title("Chapter map",1)] + bullets(["32. Create the Golden Test Set.","33. Evaluate retrieval.","34. Evaluate answer correctness and grounding.","35. Evaluate citation validity.","36. Evaluate hallucination and no-answer behavior.","37. Fix and retest defects."])
    s += [title("Learning objectives",1)] + bullets(["Explain why a passing demonstration is not the same as a validated system.","Build test questions with expected relevant article IDs and explicit safety cases.","Calculate Hit@k and Mean Reciprocal Rank in plain language.","Separate automated format checks from expert judgment about truth and support.","Write a checkpoint that preserves failures, limits, and reproducible commands."])
    s += section("32","Create the Golden Test Set",["A Golden Test Set is a small, version-controlled list of questions with an expected outcome. It functions like a marked exercise for the application: the expected relevant articles are written down before retrieval runs, so results can be compared consistently."])
    s += [title("32.1 Inputs and record format",2)] + bullets(["The project uses `evaluation/golden_test_set.json` with 10 topic questions and one each for no-evidence and patient-specific behavior.","Each topic question records an ID, question text, expected relevant article IDs, and test kind.","The initial relevance label is article-level: a result counts if its article ID is one of the expected IDs. A reviewer should confirm the labels against the issue contents page and article text.","Do not write expected answers from model output. Use the source issue and an independent reviewer to make the test set trustworthy."])
    s += [title("32.2 Coverage and balance",2)] + bullets(["Cover diverse article topics and types rather than paraphrases of one familiar study.","Include exact or metadata-oriented questions in future versions (author, year, volume, issue, article type).","Keep a negative/out-of-corpus question to test unsupported-topic behavior and a patient-specific question to test the safety boundary.","Version each test-set change. A change in expected answers changes the yardstick and should be explained in the evaluation record."])
    s += section("33","Evaluate retrieval",["Retrieval evaluation checks whether relevant source articles appear near the top of the results, before a language model has a chance to shape the response."])
    s += [title("33.1 Measures",2)] + table(["Measure","Plain-language meaning","Current target"],[
        ["Hit@6","Did at least one expected article appear in the first six returned chunks?","At least 80% of topic questions"],
        ["MRR@6","How high did the first expected article appear? Rank 1 scores 1.0, rank 2 scores 0.5, and so on.","At least 0.65 average"],
        ["No-evidence case","Did generation abstain when the issue did not support the requested claim?","No unsupported answer"],
        ["Patient boundary","Was a patient-specific request stopped before provider generation?","Boundary response and no evidence cards"]], [35*mm,90*mm,45*mm])
    s += [title("33.2 Current result and interpretation",2),P("In the first run, the expected article ranked first for all 10 topic questions: Hit@6 = 100% and MRR@6 = 1.000. These numbers describe this tiny, one-issue sample only. They should not be presented as expected accuracy for the full archive."),P("The negative question retrieved semantically related passages even though none supported the requested claim. This is an important retrieval behavior: vector search always ranks candidates unless the downstream system or calibrated cutoff abstains. The live generation test correctly returned no-evidence. The threshold in `config/rag.toml` is provisional and must be recalibrated with more journals and harder negative queries.")]
    s += section("34","Evaluate answer correctness and grounding",["Correctness asks whether the answer says what the cited article says. Grounding asks whether the retrieved passages shown as support actually justify each statement. These are not the same as a syntactically valid citation."])
    s += [title("34.1 Human review procedure",2)] + bullets(["Open `evaluation/results/step6_answer_review.csv` and inspect each answer beside the retrieved source cards.","Mark whether each statement is supported by the cited passage, not merely by another passage in the same article.","Check that study design, population, intervention or exposure, comparator, outcome, and limitations are not distorted.","Flag unsupported certainty, omitted uncertainty, invented numbers, clinical recommendations, and conflation of a commentary with original research.","Record reviewer identity/role, date, decision, correction, and source page in the durable review record."])
    s += [callout("Automated checks have a boundary","The code can ensure that a model cites an ID that belongs to the retrieved set. It cannot prove the cited passage entails the claim. That semantic check remains a human-review task for this POC.",colors.HexColor("#FFF3D8"))]
    s += section("35","Evaluate citation validity",["The first answer implementation asked the model to type citation labels inside free text. That check failed intermittently because model formatting is not a dependable data contract."])
    s += [title("35.1 Structured source IDs",2)] + bullets(["The Groq adapter now requests a strict structured response with short claim text and a list of source IDs.","The allowed ID values are built from the retrieved evidence for the current question.","`answer_question` rejects claims with no source IDs or with IDs outside the retrieved set.","After validation, the application attaches visible labels such as [S1] itself; article title, author and page come from indexed metadata, not model prose.","This blocks invented source labels and formatting drift, while leaving substantive claim support for human review."])
    s += section("36","Evaluate hallucination and no-answer behavior",["Hallucination testing includes asking about content the issue does not contain. The model must be able to say that the indexed issue does not answer the question even when search retrieves loosely related passages."])
    s += [title("36.1 Safety observations",2)] + bullets(["The no-evidence test retrieves some broad semantic candidates, then Groq returns the configured no-evidence response instead of unsupported claims.","The patient-specific test is blocked locally before a provider call. This prototype phrase check is narrow and must not be described as a complete clinical safety system.","An empty result set and a retrieved-but-insufficient evidence set are different states; both must avoid an unsupported answer.","Retain the source passages in the response so the user can inspect the basis directly."])
    s += section("37","Fix and retest defects",["A validation failure is useful evidence. Record it, change one component at a time, and rerun the same Golden Test Set so improvements can be distinguished from accidental changes."])
    s += [title("37.1 Implemented correction",2)] + bullets(["Defect: free-form citation validation produced safe but inconsistent rejections.","Correction: structured claims with allowed source IDs; the app verifies IDs against retrieved evidence and renders the final source labels.","Retest: a grounded KISS question produced an answer with [S1], while the deliberately out-of-corpus question returned a no-evidence response.","Retrieval defect found: the issue returns related candidate passages for the negative question. The model abstains in the live test; broader negative-set calibration remains open."])
    s += [title("Reproducible commands",1),P("From the Project folder, activate the virtual environment and run the following. The first command performs local evaluation only. The second sends two question-plus-passage requests to Groq and is gated by the project consent setting."),P("python scripts\\evaluate_step6.py<br/>python scripts\\evaluate_step6.py --live-answers", "Calloutx")]
    s += [title("Checkpoint and gate",1),P("The current checkpoint is `data/processed/step6_checkpoint.md`; detailed metrics are in `evaluation/results/step6_evaluation.json`, and generated responses for review are in `evaluation/results/step6_answer_review.csv`. Current automated results: Hit@6 1.000, MRR@6 1.000, patient boundary PASS, structured citation-format test PASS, and no-evidence generation PASS."),callout("Step 6 status: automated POC checks pass; expert review remains","Before Step 7 demonstration, a qualified reviewer should examine the generated answer and confirm article-level relevance labels. This is not clinical validation, and one issue is not enough to claim general performance.",colors.HexColor("#FFF3D8"))]
    s += [title("References and glossary",1)] + bullets(["Ver 1 - Complete Implementation Guide for POC.pdf, Phase 6 Validation, actions 32-37.","Ver 1 - Master Guide for POC.pdf, quality, grounding, citation, safety and staged-scope principles.","Project files: `evaluation/golden_test_set.json`, `scripts/evaluate_step6.py`, `src/journal_assistant/rag/answering.py`, `src/journal_assistant/rag/providers/groq_provider.py`, and `data/processed/step6_checkpoint.md`."])
    add_glossary(s,[["Golden Test Set","Versioned questions with prewritten expected relevant sources or safety outcomes."],["Hit@k","Share of questions with at least one expected source in the first k results."],["Mean Reciprocal Rank","Average score based on how high the first expected source appears."],["Grounding","Whether the evidence actually supports what the answer claims."],["Abstention","A deliberate no-answer response when evidence is missing or insufficient."],["Structured output","Machine-readable model output constrained by a schema."],["Citation validity","Whether a citation points to a real retrieved source; validity alone does not prove support."]])
    make_pdf("Step6.pdf","Step 6 | Validation",s)

def build_step7():
    s=[]
    cover(s,"STEP 7 | DEMONSTRATION","Package a transparent, repeatable editor walkthrough","This chapter follows roadmap actions 38-43. It selects seven demonstrations, improves the UI with reusable examples and clearer labels, prepares a presentation script, updates the technical manual, runs a package checkpoint, and defines what ready means for this limited POC.")
    s += [title("Chapter map",1)] + bullets(["38. Select 5-7 demonstration questions.","39. Polish interface for the intended audience.","40. Prepare a reproducible demonstration script.","41. Prepare the technical manual.","42. Prepare the POC test report.","43. Declare POC V1 ready only against explicit criteria."])
    s += [title("Learning objectives",1)] + bullets(["Build a brief demonstration around visible user needs and evidence behavior.","Use a scripted walkthrough without hiding failures or uncertainty.","Distinguish demo readiness from product, legal, and clinical readiness.","Keep a reproducible test report with known limitations and review gates."])
    s += section("38","Select 5-7 demonstration questions",["A short editor demonstration should show representative wins, a source trail, and safety behavior. Seven curated questions are recorded in `evaluation/demo_questions.json` and appear as examples in the Streamlit interface."])
    s += table(["Path","Example","What it demonstrates"],[
        ["Grounded topic search","KISS study comparison","Answer with source ID, article title and page provenance."],
        ["Article type","IVIg systematic review","Display evidence with its category and inspect the passages."],
        ["Topic discovery","Dietary fatty acids and asthma","Find an article from a topic-style question."],
        ["Second research topic","Donor milk vs preterm formula","Show another indexed original article."],
        ["Guideline synopsis","ESPGHAN synopsis","Show retrieval across a different editorial type."],
        ["No evidence","Pediatric brain tumors caused by moonlight","Test the assistant's abstention behavior."],
        ["Safety boundary","Personal child fever question","Demonstrate a refusal of individualized advice."]],[32*mm,61*mm,77*mm])
    s += [P("The question list is not a substitute for an independent quality review. Before presenting a generated clinical-literature claim, inspect it against the article passage and confirm the cited page.")]
    s += section("39","Polish interface for the intended audience",["The Step 7 changes improve discoverability and communicate the app's boundaries while retaining the fast local Streamlit prototype."])
    s += bullets(["The interface now offers a journal-specific example selector populated from a data file, not a hard-coded UI list.","Search is labelled accurately as local hybrid lexical and semantic retrieval; embeddings are identified as local.","The evidence-handling explanation and literature-only warning are visible before users search.","The About section states the access-review status and warns against redistributing source PDFs.","The optional external-processing notice remains visible when the consent gate is enabled."])
    s += section("40","Prepare a reproducible demonstration script",["`demo/Demonstration_Script.md` provides a 10-15 minute opening, seven examples, expected talking points, a closing statement, preflight steps, and troubleshooting. Use the same questions each time so presenters do not select only favorable outputs."])
    s += [title("40.1 Before the meeting",2)] + bullets(["Run `python scripts\\check_step7.py` and review both pass and pending items.","Keep `.env` and the API key private. Do not display the environment file.","Explain that when external processing is enabled, the typed question and retrieved passages are sent to Groq; documents and embeddings are local.","If provider access fails, continue only with local search and source inspection; say answer generation is unavailable.","Do not invite personal patient cases during the demonstration."])
    s += section("41","Prepare the technical manual",["The cumulative manual is extended one phase at a time and follows the roadmap numbering. `manuals/Step7.pdf` explains the demo question selection, user-facing changes, demonstration script, report, and readiness decision. Step 5's manual was also corrected to describe the current conditional answer path."])
    s += bullets(["Keep action numbers 38-43 aligned with the Implementation Guide.","Document implementation choices, commands and reasoning for AI students.","Record limits and teach what the automated checks cannot establish.","Preserve previous manual chapters and add this installment as a separate PDF for review."])
    s += section("42","Prepare the POC test report",["`scripts/check_step7.py` verifies the required demo materials, the seven-example question set, the latest Step 5 UI checkpoint, and the Step 6 evaluation. It writes both `data/processed/step7_checkpoint.md` and `evaluation/results/step7_poc_test_report.md`."])
    s += [title("42.1 What the report does not prove",2)] + bullets(["A passing check confirms files and selected automated results exist; it does not independently re-run the live provider test.","The answer review CSV still needs a human reviewer to confirm claim support and expected-source labels.","The journal profile records access/reuse review as pending/unconfirmed.","One issue and seven demo examples cannot establish archive-wide, clinical, or cross-journal performance."])
    s += section("43","Declare POC V1 ready only against explicit criteria",["Readiness is a scoped decision. A working interface by itself does not establish that the corpus is complete, that the sources may be redistributed, or that the assistant is clinically safe."])
    s += table(["Readiness level","Criteria","Current determination"],[
        ["Controlled editor walkthrough","Demo script and examples exist; UI smoke check passes; Step 6 automated retrieval/citation/abstention checks pass; limitations are disclosed.","DEMO PACKAGE READY WITH DISCLOSURES if Step 7 checkpoint passes."],
        ["POC V1 validated","Expert answer grounding and relevance review complete; open defects resolved or accepted against targets.","NOT DECLARED; human review remains pending."],
        ["Distribution/deployment","Written source/reuse basis, security review, API-key custody plan, privacy review, user testing and deployment validation complete.","NOT READY / NOT ASSESSED."]],[34*mm,79*mm,57*mm])
    s += [callout("Current Step 7 decision","The demonstration package is prepared for a controlled editor walkthrough with disclosures. This is not a declaration of clinical validation, product readiness, permission to redistribute journal content, or approval to deploy.",colors.HexColor("#FFF3D8")),P("Run `python scripts\\check_step7.py` after any change to the demo files or UI. Keep the resulting report with the demonstration materials. A failed check should be fixed or explicitly disclosed before presenting.")]
    s += [title("References and glossary",1)] + bullets(["Ver 1 - Complete Implementation Guide for POC.pdf, Phase 7 Demonstration, actions 38-43.","Ver 1 - Master Guide for POC.pdf, product boundaries, evidence traceability and risk disclosures.","Project files: `evaluation/demo_questions.json`, `demo/Demonstration_Script.md`, `scripts/check_step7.py`, and `evaluation/results/step7_poc_test_report.md`."])
    add_glossary(s,[["Demo readiness","Prepared materials and basic checks for a bounded walkthrough; it is not product approval."],["Disclosure","A clear statement of scope, limitations, data flow, and unresolved items."],["External processing","Sending the question and retrieved passages to a remote model provider."],["Readiness criterion","A concrete, checkable condition required for a particular readiness level."],["Human grounding review","A reviewer checks that each generated claim is justified by its cited source passage."]])
    make_pdf("Step7.pdf","Step 7 | Demonstration",s)

if __name__ == "__main__":
    import sys
    chapter=sys.argv[1] if len(sys.argv)>1 else "step3"
    if chapter=="step4": build_step4(); print("Created Step4.pdf in", OUT)
    elif chapter=="step5": build_step5(); print("Created Step5.pdf in", OUT)
